def _interact_sif_shadowhunter(
    dialog_id: int,
    *,
    accept_reward: bool = False,
    expected_quest_id: int = 0,
) -> Generator[Any, Any, bool]:
    """Interact with the live Sif variant and optionally accept its reward."""
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.FrameTree import Frame, FrameId
    from Py4GWCoreLib.Py4GWcorelib import Utils
    from Py4GWCoreLib.UIManager import UIManager

    def accept_visible_reward() -> tuple[bool, str]:
        if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
            if UIManager.ClickDialogButton(1, debug=False):
                return True, "dialog_button_1"
        accept_button = Frame(FrameId.AcceptButton)
        if accept_button.exists and accept_button.is_usable:
            accept_button.click()
            return True, "frame_accept_button"
        return False, "none"

    if accept_reward and expected_quest_id:
        quest_log_ids = {int(value) for value in (Quest.GetQuestLogIds() or [])}
        if int(expected_quest_id) not in quest_log_ids:
            SESSION_LOG.write(
                f"sif_reward_skipped quest_id={expected_quest_id} dialog={hex(dialog_id)} "
                "reason=quest_already_cleared"
            )
            return True

    player_xy = Player.GetXY()
    shared_agents = AgentArray.GetAgentArray()
    context = GWContext.AgentArray.GetContext()
    context_agents = context.GetAgentArray() if context is not None else []
    all_agents = list(dict.fromkeys([*shared_agents, *context_agents]))
    resolution = "model_id"
    candidates = [
        agent_id
        for agent_id in all_agents
        if Agent.GetModelID(agent_id) in SIF_SHADOWHUNTER_MODEL_IDS
    ]

    if not candidates:
        resolution = "decoded_name"
        candidates = [
            agent_id
            for agent_id in all_agents
            if "sif shadowhunter" in Agent.GetNameByID(agent_id).strip().lower()
        ]

    if not candidates:
        resolution = "npc_at_known_position"
        candidates = [
            agent_id
            for agent_id in all_agents
            if Agent.IsLiving(agent_id)
            and Agent.IsNPC(agent_id)
            and Utils.Distance(SIF_SHADOWHUNTER_XY, Agent.GetXY(agent_id)) <= 250.0
        ]

    if not candidates:
        nearby = []
        for agent_id in all_agents:
            if not Agent.IsLiving(agent_id):
                continue
            agent_xy = Agent.GetXY(agent_id)
            distance = Utils.Distance(player_xy, agent_xy)
            if distance <= 1500.0:
                nearby.append(
                    f"id={agent_id},model={Agent.GetModelID(agent_id)},name={Agent.GetNameByID(agent_id)!r},"
                    f"xy={agent_xy},distance={distance:.1f},npc={Agent.IsNPC(agent_id)}"
                )
        message = (
            f"sif_lookup_failed map={Map.GetMapID()} player_xy={player_xy} "
            f"models={SIF_SHADOWHUNTER_MODEL_IDS} shared_count={len(shared_agents)} "
            f"context_count={len(context_agents)} merged_count={len(all_agents)} nearby={nearby}"
        )
        SESSION_LOG.write(message)
        ConsoleLog(MODULE_NAME, "Sif Shadowhunter was not found in the live agent array.", Console.MessageType.Error)
        bot.config.state_description = "Blocked: Sif Shadowhunter not found"
        # A self-managed state advances when its generator returns. Keep this
        # state alive so the route cannot leave Sifhalla after failed dialog.
        while bot.config.fsm_running:
            yield from Routines.Yield.wait(1000)
        return False

    agent_id = min(candidates, key=lambda candidate: Utils.Distance(player_xy, Agent.GetXY(candidate)))
    model_id = Agent.GetModelID(agent_id)
    agent_xy = Agent.GetXY(agent_id)
    SESSION_LOG.write(
        f"sif_lookup_success map={Map.GetMapID()} agent_id={agent_id} model_id={model_id} "
        f"agent_name={Agent.GetNameByID(agent_id)!r} agent_xy={agent_xy} player_xy={player_xy} "
        f"dialog={hex(dialog_id)} resolution={resolution} shared_count={len(shared_agents)} "
        f"context_count={len(context_agents)}"
    )

    yield from bot.Dialogs._coro_pause_hero_ai()
    yield from Routines.Yield.Player.InteractAgent(agent_id)
    yield from Routines.Yield.wait(500)
    Player.SendDialog(dialog_id)
    yield from Routines.Yield.wait(500)
    if accept_reward:
        accept_deadline = time.monotonic() + 6.0
        accepted = False
        method = "none"
        while bot.config.fsm_running and time.monotonic() < accept_deadline:
            accepted, method = accept_visible_reward()
            if accepted:
                break
            yield from Routines.Yield.wait(100)
        if accepted:
            verify_deadline = time.monotonic() + 6.0
            while bot.config.fsm_running and time.monotonic() < verify_deadline:
                if not expected_quest_id or int(expected_quest_id) not in {
                    int(value) for value in (Quest.GetQuestLogIds() or [])
                }:
                    break
                yield from Routines.Yield.wait(100)
        quest_cleared = (
            accepted
            and (
                not expected_quest_id
                or int(expected_quest_id) not in {
                    int(value) for value in (Quest.GetQuestLogIds() or [])
                }
            )
        )
        yield from bot.Dialogs._coro_restore_hero_ai()
        SESSION_LOG.write(
            f"sif_reward_accept_result agent_id={agent_id} model_id={model_id} "
            f"dialog={hex(dialog_id)} accepted={accepted} method={method} "
            f"expected_quest_id={expected_quest_id} quest_cleared={quest_cleared}"
        )
        if not quest_cleared:
            ConsoleLog(
                MODULE_NAME,
                "Sif's reward was not confirmed; waiting here instead of continuing.",
                Console.MessageType.Error,
            )
            bot.config.state_description = "Blocked: Sif reward was not confirmed"
            while bot.config.fsm_running:
                if not expected_quest_id or int(expected_quest_id) not in {
                    int(value) for value in (Quest.GetQuestLogIds() or [])
                }:
                    SESSION_LOG.write(
                        f"sif_reward_manual_recovery quest_id={expected_quest_id}"
                    )
                    return True
                yield from Routines.Yield.wait(250)
            return False
        return True
    yield from bot.Dialogs._coro_restore_hero_ai()
    SESSION_LOG.write(
        f"sif_dialog_sent agent_id={agent_id} model_id={model_id} dialog={hex(dialog_id)}"
    )
    return True


def _interact_outrunner_remlok(
    dialog_id: int,
    *,
    expected_quest_id: int = 0,
) -> Generator[Any, Any, bool]:
    """Path to Remlok, accept his quest, and verify it entered the quest log."""
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.FrameTree import Frame, FrameId
    from Py4GWCoreLib.Py4GWcorelib import Utils
    from Py4GWCoreLib.UIManager import UIManager

    if expected_quest_id and expected_quest_id in set(Quest.GetQuestLogIds() or []):
        SESSION_LOG.write(
            f"remlok_quest_accept_skipped quest_id={expected_quest_id} "
            f"dialog={hex(dialog_id)} reason=already_in_quest_log"
        )
        return True

    def accept_visible_quest() -> tuple[bool, str]:
        if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
            if UIManager.ClickDialogButton(1, debug=False):
                return True, "dialog_button_1"
        accept_button = Frame(FrameId.AcceptButton)
        if accept_button.exists and accept_button.is_usable:
            accept_button.click()
            return True, "frame_accept_button"
        return False, "none"

    def full_agent_array() -> tuple[list[int], list[int], list[int]]:
        shared = AgentArray.GetAgentArray()
        context = GWContext.AgentArray.GetContext()
        context_values = context.GetAgentArray() if context is not None else []
        merged = list(dict.fromkeys([*shared, *context_values]))
        return shared, context_values, merged

    player_xy = Player.GetXY()
    start_distance = Utils.Distance(player_xy, OUTRUNNER_REMLOK_XY)
    if start_distance > 1000.0:
        SESSION_LOG.write(
            f"remlok_approach_start map={Map.GetMapID()} player_xy={player_xy} "
            f"target_xy={OUTRUNNER_REMLOK_XY} distance={start_distance:.1f} "
            f"source_route='ROUTE-20260803-104223-618'"
        )
        movement_success = yield from Routines.Yield.Movement.FollowPath(
            path_points=list(DRAKKAR_TO_REMLOK_ROUTE_XY),
            tolerance=300.0,
            timeout=-1,
            custom_pause_fn=lambda: Routines.Checks.Agents.InDanger(),
            stop_on_party_wipe=False,
            autopath=False,
        )

        player_xy = Player.GetXY()
        remaining_distance = Utils.Distance(player_xy, OUTRUNNER_REMLOK_XY)
        SESSION_LOG.write(
            f"remlok_approach_finished map={Map.GetMapID()} player_xy={player_xy} "
            f"remaining_distance={remaining_distance:.1f} "
            f"movement_success={movement_success} route_points={len(DRAKKAR_TO_REMLOK_ROUTE_XY)}"
        )
        if remaining_distance > 1200.0:
            ConsoleLog(
                MODULE_NAME,
                "Could not reach Outrunner Remlok on the recorded Drakkar route.",
                Console.MessageType.Error,
            )
            bot.config.state_description = "Blocked: path to Outrunner Remlok failed"
            while bot.config.fsm_running:
                yield from Routines.Yield.wait(1000)
            return False

    # Names and NPC arrays may populate a few frames after movement/map load.
    # Reacquire instead of permanently blocking on one early snapshot.
    shared_agents: list[int] = []
    context_agents: list[int] = []
    all_agents: list[int] = []
    candidates: list[int] = []
    resolution = "decoded_name"
    lookup_deadline = time.monotonic() + 10.0
    while bot.config.fsm_running and time.monotonic() < lookup_deadline:
        shared_agents, context_agents, all_agents = full_agent_array()
        resolution = "decoded_name"
        candidates = [
            agent_id
            for agent_id in all_agents
            if Agent.IsLiving(agent_id)
            and "outrunner remlok" in (Agent.GetNameByID(agent_id) or "").strip().lower()
        ]

        if not candidates:
            resolution = "npc_at_known_position"
            candidates = [
                agent_id
                for agent_id in all_agents
                if Agent.IsLiving(agent_id)
                and Agent.IsNPC(agent_id)
                and Utils.Distance(OUTRUNNER_REMLOK_XY, Agent.GetXY(agent_id)) <= 300.0
            ]
        if candidates:
            break
        yield from Routines.Yield.wait(250)

    if not candidates:
        nearby = []
        for agent_id in all_agents:
            if not Agent.IsLiving(agent_id):
                continue
            agent_xy = Agent.GetXY(agent_id)
            distance = Utils.Distance(OUTRUNNER_REMLOK_XY, agent_xy)
            if distance <= 1500.0:
                nearby.append(
                    f"id={agent_id},model={Agent.GetModelID(agent_id)},name={Agent.GetNameByID(agent_id)!r},"
                    f"xy={agent_xy},distance_to_remlok={distance:.1f},npc={Agent.IsNPC(agent_id)}"
                )
        message = (
            f"remlok_lookup_failed map={Map.GetMapID()} player_xy={player_xy} "
            f"target_xy={OUTRUNNER_REMLOK_XY} shared_count={len(shared_agents)} "
            f"context_count={len(context_agents)} merged_count={len(all_agents)} nearby={nearby}"
        )
        SESSION_LOG.write(message)
        ConsoleLog(MODULE_NAME, "Outrunner Remlok was not found in the full live agent array.", Console.MessageType.Error)
        bot.config.state_description = "Blocked: Outrunner Remlok not found"
        while bot.config.fsm_running:
            yield from Routines.Yield.wait(1000)
        return False

    agent_id = min(
        candidates,
        key=lambda candidate: Utils.Distance(OUTRUNNER_REMLOK_XY, Agent.GetXY(candidate)),
    )
    model_id = Agent.GetModelID(agent_id)
    agent_xy = Agent.GetXY(agent_id)
    SESSION_LOG.write(
        f"remlok_lookup_success map={Map.GetMapID()} agent_id={agent_id} model_id={model_id} "
        f"agent_name={Agent.GetNameByID(agent_id)!r} agent_xy={agent_xy} player_xy={player_xy} "
        f"dialog={hex(dialog_id)} resolution={resolution} shared_count={len(shared_agents)} "
        f"context_count={len(context_agents)}"
    )

    yield from bot.Dialogs._coro_pause_hero_ai()
    yield from Routines.Yield.Player.InteractAgent(agent_id)
    # Remlok's conversation opens asynchronously. Follow the restored SoD
    # interaction order: wait for a visible choice first, then use the known
    # dialog only as a fallback and retry the visible choice.
    visible_deadline = time.monotonic() + 4.0
    while bot.config.fsm_running and time.monotonic() < visible_deadline:
        if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
            break
        yield from Routines.Yield.wait(100)

    accepted, accept_method = accept_visible_quest()
    fallback_sent = False
    if not accepted:
        Player.SendDialog(dialog_id)
        fallback_sent = True
        fallback_deadline = time.monotonic() + 4.0
        while bot.config.fsm_running and time.monotonic() < fallback_deadline:
            if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
                break
            yield from Routines.Yield.wait(100)
        accepted, accept_method = accept_visible_quest()

    quest_verified = not expected_quest_id
    verify_deadline = time.monotonic() + 6.0
    while bot.config.fsm_running and time.monotonic() < verify_deadline:
        if expected_quest_id in set(Quest.GetQuestLogIds() or []):
            quest_verified = True
            break
        yield from Routines.Yield.wait(100)
    yield from bot.Dialogs._coro_restore_hero_ai()
    SESSION_LOG.write(
        f"remlok_dialog_sent agent_id={agent_id} model_id={model_id} "
        f"dialog={hex(dialog_id)} accepted={accepted} accept_method={accept_method} "
        f"fallback_sent={fallback_sent} expected_quest_id={expected_quest_id} "
        f"quest_verified={quest_verified}"
    )
    if not quest_verified:
        ConsoleLog(
            MODULE_NAME,
            "Outrunner Remlok's quest was not accepted; waiting here before Sepulchre.",
            Console.MessageType.Error,
        )
        bot.config.state_description = "Blocked: manually accept Remlok's quest to continue"
        SESSION_LOG.write(
            "remlok_quest_accept_waiting_for_manual_recovery "
            f"quest_id={expected_quest_id} map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        while bot.config.fsm_running:
            if expected_quest_id in set(Quest.GetQuestLogIds() or []):
                SESSION_LOG.write(
                    "remlok_quest_accept_manual_recovery "
                    f"quest_id={expected_quest_id} map={Map.GetMapID()}"
                )
                bot.config.state_description = "Running: Remlok quest accepted"
                return True
            yield from Routines.Yield.wait(250)
        return False
    return True


class _SkillsUnlockerInteractionRuntime(Py4GWInteractionRuntime):
    def __init__(
        self,
        interaction_key: str,
        verify_fn: Callable[[PostconditionSpec], bool],
    ) -> None:
        self.interaction_key = interaction_key
        self.hero_ai_status = bot.config.upkeep.hero_ai.is_active()
        self.hero_ai_pause_status = bool(
            hasattr(bot.config.upkeep, "hero_ai_paused")
            and bot.config.upkeep.hero_ai_paused.is_active()
        )
        super().__init__(
            pause_automation=self._pause_hero_ai,
            restore_automation=self._restore_hero_ai,
            verify=verify_fn,
            diagnostic_sink=self._record_event,
        )

    def _record_event(self, event: dict[str, Any]) -> None:
        SESSION_LOG.write(
            f"reliable_interaction key={self.interaction_key!r} event={dict(event)!r}"
        )

    def _pause_hero_ai(self) -> None:
        if hasattr(bot.config.upkeep, "hero_ai_paused"):
            bot.config.upkeep.hero_ai_paused.set_now("active", True)
        else:
            bot.config.upkeep.hero_ai.set_now("active", False)

    def _restore_hero_ai(self) -> None:
        if hasattr(bot.config.upkeep, "hero_ai_paused"):
            bot.config.upkeep.hero_ai_paused.set_now(
                "active", self.hero_ai_pause_status
            )
        bot.config.upkeep.hero_ai.set_now("active", self.hero_ai_status)


def _run_reliable_interaction(
    interaction_key: str,
    spec_factory: Callable[[], InteractionSpec],
    verify_fn: Callable[[PostconditionSpec], bool],
) -> Generator[Any, Any, bool]:
    SESSION_LOG.write(
        f"interaction_state_enter key={interaction_key!r} map={Map.GetMapID()} "
        f"player_xy={Player.GetXY()}"
    )
    try:
        spec = spec_factory()
        SESSION_LOG.write(
            f"interaction_spec_built key={interaction_key!r} "
            f"profile={spec.profile.value!r} sources={spec.source_capture_ids!r}"
        )
        runtime = _SkillsUnlockerInteractionRuntime(interaction_key, verify_fn)
        controller = ReliableInteractionController(spec, runtime)
        SESSION_LOG.write(
            f"interaction_controller_start key={interaction_key!r} "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        success = yield from run_coroutine_adapter(
            controller,
            Routines.Yield.wait,
        )
        SESSION_LOG.write(
            f"interaction_state_{'success' if success else 'failure'} "
            f"key={interaction_key!r} map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        return bool(success)
    except Exception as error:
        SESSION_LOG.write(
            f"interaction_state_exception key={interaction_key!r} "
            f"error_type={type(error).__name__!r} error={str(error)!r} "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        ConsoleLog(
            MODULE_NAME,
            f"Reliable interaction failed before completion: {interaction_key}",
            Console.MessageType.Error,
        )
        return False


def _run_reliable_interaction_boundary(
    interaction_key: str,
    boundary_factory: Callable[[], InteractionBoundarySpec],
    verify_fn: Callable[[PostconditionSpec], bool],
    *,
    pause_on_danger: bool = True,
) -> Generator[Any, Any, bool]:
    SESSION_LOG.write(
        f"interaction_boundary_state_enter key={interaction_key!r} map={Map.GetMapID()} "
        f"player_xy={Player.GetXY()}"
    )
    try:
        boundary = boundary_factory()
        SESSION_LOG.write(
            f"interaction_boundary_spec_built key={interaction_key!r} "
            f"route_points={len(boundary.route_points)} "
            f"standoff={boundary.route_standoff_xy!r} "
            f"target={boundary.interaction.target.expected_xy!r} "
            f"approach={boundary.interaction.approach.player_approach_xy!r}"
        )
        runtime = _SkillsUnlockerInteractionRuntime(interaction_key, verify_fn)
        route_executor = make_follow_path_boundary_executor(
            Routines.Yield.Movement.FollowPath,
            timeout=-1,
            custom_pause_fn=(
                (lambda: Routines.Checks.Agents.InDanger())
                if pause_on_danger
                else (lambda: False)
            ),
            stop_on_party_wipe=False,
            autopath=False,
        )
        controller = InteractionBoundaryController(
            boundary,
            runtime,
            route_executor,
        )
        SESSION_LOG.write(
            f"interaction_boundary_controller_start key={interaction_key!r} "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        success = yield from run_boundary_coroutine_adapter(
            controller,
            Routines.Yield.wait,
        )
        SESSION_LOG.write(
            f"interaction_boundary_state_{'success' if success else 'failure'} "
            f"key={interaction_key!r} map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        return bool(success)
    except Exception as error:
        SESSION_LOG.write(
            f"interaction_boundary_state_exception key={interaction_key!r} "
            f"error_type={type(error).__name__!r} error={str(error)!r} "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        ConsoleLog(
            MODULE_NAME,
            f"Reliable interaction boundary failed before completion: {interaction_key}",
            Console.MessageType.Error,
        )
        return False


def _interact_outrunner_remlok_reliable(
    dialog_id: int,
    *,
    expected_quest_id: int,
) -> Generator[Any, Any, bool]:
    """Hand the recorded route off before Remlok's collision-sensitive approach."""

    if int(expected_quest_id) in {
        int(value) for value in (Quest.GetQuestLogIds() or [])
    }:
        SESSION_LOG.write(
            f"remlok_quest_accept_skipped quest_id={expected_quest_id} "
            "reason=already_in_quest_log"
        )
        return True

    def verify(_postcondition: PostconditionSpec) -> bool:
        return int(expected_quest_id) in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="IAU Remlok quest acceptance",
            profile=InteractionProfile.QUEST_CONVERSATION,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=6267,
                expected_xy=OUTRUNNER_REMLOK_XY,
                search_radius=350.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=DRAKKAR_TO_REMLOK_ROUTE_XY[-1],
                tolerance=75.0,
                target_tolerance=140.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button=1,
                raw_context_ids=(int(dialog_id),),
                response_timeout_ms=4_000,
                allow_raw_without_visible_dialog=False,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_ACTIVE,
                value=int(expected_quest_id),
                description="The Anvil of Dragrimmar is active",
            ),
            retry=RetryPolicy(
                max_attempts=4,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            close_stale_dialog=True,
            allow_preexisting_postcondition=True,
            source_capture_ids=("ROUTE-20260803-104223-618",),
        )
        return InteractionBoundarySpec(
            name="IAU route-to-Remlok quest boundary",
            # The final captured point is the controller-owned safe approach.
            # Stop the ordinary route one point earlier so collision avoidance
            # cannot prevent the interaction state from ever starting.
            route_points=tuple(DRAKKAR_TO_REMLOK_ROUTE_XY[:-1]),
            route_standoff_xy=DRAKKAR_TO_REMLOK_ROUTE_XY[-2],
            route_tolerance=150.0,
            handoff_radius=250.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "IAU:REMLOK:QUEST-809",
        build_boundary,
        verify,
    )
    if success:
        return True

    ConsoleLog(
        MODULE_NAME,
        "Outrunner Remlok's quest was not accepted; waiting here before Sepulchre.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: manually accept Remlok's quest to continue"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_ACTIVE, expected_quest_id)):
            SESSION_LOG.write(
                f"remlok_quest_accept_manual_recovery quest_id={expected_quest_id}"
            )
            bot.config.state_description = "Running: Remlok quest accepted"
            return True
        yield from Routines.Yield.wait(250)
    return False


def _take_optional_blessing_at_xy(
    npc_xy: Tuple[float, float],
    dialog_id: int,
    preferred_model_id: int = 0,
    label: str = "blessing",
) -> Generator[Any, Any, bool]:
    """Take or refresh an EOTN blessing, including first-time Norn challenges."""
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.Py4GWcorelib import Utils
    from Py4GWCoreLib.UIManager import UIManager

    def has_eotn_blessing() -> bool:
        player_id = Player.GetAgentID()
        return any(
            Effects.EffectExists(player_id, effect_id)
            for effect_id in EOTN_BLESSING_EFFECT_IDS
        )

    def allegiance_value(living_agent_id: int) -> int:
        allegiance = Agent.GetAllegiance(living_agent_id)
        return allegiance[0] if isinstance(allegiance, tuple) else allegiance

    def click_first_visible_choice(
        timeout_seconds: float = 4.0,
    ) -> Generator[Any, Any, bool]:
        deadline = time.monotonic() + timeout_seconds
        while bot.config.fsm_running and time.monotonic() < deadline:
            if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
                if UIManager.ClickDialogButton(1, debug=False):
                    return True
            yield from Routines.Yield.wait(100)
        return False

    shared_agents = AgentArray.GetAgentArray()
    context = GWContext.AgentArray.GetContext()
    context_agents = context.GetAgentArray() if context is not None else []
    all_agents = list(dict.fromkeys([*shared_agents, *context_agents]))

    candidates = []
    resolution = "preferred_model_at_position"
    if preferred_model_id:
        candidates = [
            agent_id
            for agent_id in all_agents
            if Agent.IsLiving(agent_id)
            and Agent.GetModelID(agent_id) == preferred_model_id
            and Utils.Distance(npc_xy, Agent.GetXY(agent_id)) <= 350.0
        ]

    if not candidates:
        resolution = "nearest_npc_to_captured_position"
        candidates = [
            agent_id
            for agent_id in all_agents
            if Agent.IsLiving(agent_id)
            and Agent.IsNPC(agent_id)
            and Utils.Distance(npc_xy, Agent.GetXY(agent_id)) <= 175.0
        ]

    if not candidates:
        SESSION_LOG.write(
            f"optional_blessing_lookup_failed label={label!r} map={Map.GetMapID()} "
            f"npc_xy={npc_xy} preferred_model_id={preferred_model_id} "
            f"shared_count={len(shared_agents)} context_count={len(context_agents)}"
        )
        ConsoleLog(
            MODULE_NAME,
            f"Optional blessing skipped: {label} NPC was not found.",
            Console.MessageType.Warning,
        )
        return False

    agent_id = min(candidates, key=lambda candidate: Utils.Distance(npc_xy, Agent.GetXY(candidate)))
    player_to_agent = Utils.Distance(Player.GetXY(), Agent.GetXY(agent_id))
    if player_to_agent > 160.0:
        agent_xy = Agent.GetXY(agent_id)
        scale = 110.0 / max(player_to_agent, 1.0)
        safe_approach_xy = (
            agent_xy[0] + (Player.GetXY()[0] - agent_xy[0]) * scale,
            agent_xy[1] + (Player.GetXY()[1] - agent_xy[1]) * scale,
        )
        yield from bot.Move._coro_xy(
            *safe_approach_xy,
            step_name=f"Approach {label}",
            forced_timeout=15000,
            fail_on_unmanaged=False,
        )

        context = GWContext.AgentArray.GetContext()
        context_agents = context.GetAgentArray() if context is not None else []
        all_agents = list(dict.fromkeys([*AgentArray.GetAgentArray(), *context_agents]))
        candidates = [
            candidate
            for candidate in all_agents
            if Agent.IsLiving(candidate)
            and (
                not preferred_model_id
                or Agent.GetModelID(candidate) == preferred_model_id
            )
            and Utils.Distance(npc_xy, Agent.GetXY(candidate)) <= 350.0
        ]
        if not candidates:
            SESSION_LOG.write(
                f"optional_blessing_reacquire_failed label={label!r} "
                f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
            )
            return False
        agent_id = min(
            candidates,
            key=lambda candidate: Utils.Distance(npc_xy, Agent.GetXY(candidate)),
        )
        player_to_agent = Utils.Distance(Player.GetXY(), Agent.GetXY(agent_id))
    if player_to_agent > 175.0:
        SESSION_LOG.write(
            f"optional_blessing_too_far label={label!r} agent_id={agent_id} "
            f"player_to_agent={player_to_agent:.1f}"
        )
        return False
    SESSION_LOG.write(
        f"optional_blessing_lookup_success label={label!r} map={Map.GetMapID()} "
        f"agent_id={agent_id} model_id={Agent.GetModelID(agent_id)} "
        f"agent_name={Agent.GetNameByID(agent_id)!r} agent_xy={Agent.GetXY(agent_id)} "
        f"dialog={hex(dialog_id)} resolution={resolution} "
        f"player_xy={Player.GetXY()} player_to_agent={player_to_agent:.1f} "
        f"agent_to_capture={Utils.Distance(npc_xy, Agent.GetXY(agent_id)):.1f}"
    )

    already_blessed = has_eotn_blessing()
    yield from bot.Dialogs._coro_pause_hero_ai()
    yield from Routines.Yield.Player.InteractAgent(agent_id)

    # With an active blessing, shrine interaction is only a kill-count/bonus
    # check. The response is informational and the bonus is awarded by the
    # interaction, so do not blindly choose its first button.
    if already_blessed:
        yield from Routines.Yield.wait(1200)
        dialog_visible = UIManager.IsNPCDialogVisible()
        button_count = UIManager.GetDialogButtonCount() if dialog_visible else 0
        yield from bot.Dialogs._coro_restore_hero_ai()
        SESSION_LOG.write(
            f"optional_blessing_refresh label={label!r} agent_id={agent_id} "
            f"model_id={Agent.GetModelID(agent_id)} already_blessed=True "
            f"dialog_visible={dialog_visible} button_count={button_count}"
        )
        return bool(dialog_visible)

    # An unblessed character gets a Yes/No prompt. For an ordinary shrine,
    # Yes applies the title effect. For a first-time Norn challenger, Yes
    # starts the fight instead; live allegiance below tells those apart.
    clicked = yield from click_first_visible_choice()

    yield from bot.Dialogs._coro_restore_hero_ai()

    blessed = has_eotn_blessing()
    became_hostile = False
    outcome_deadline = time.monotonic() + 8.0
    while bot.config.fsm_running and time.monotonic() < outcome_deadline:
        if has_eotn_blessing():
            blessed = True
            break
        if allegiance_value(agent_id) == 3:
            became_hostile = True
            break
        yield from Routines.Yield.wait(100)

    if became_hostile:
        SESSION_LOG.write(
            f"optional_blessing_norn_challenge_started label={label!r} "
            f"agent_id={agent_id} model_id={Agent.GetModelID(agent_id)}"
        )
        ConsoleLog(
            MODULE_NAME,
            f"First-time Norn challenge started at {label}; waiting for the party to win.",
            Console.MessageType.Info,
        )

        # HeroAI is active again here, so the party can fight normally.
        challenge_deadline = time.monotonic() + 150.0
        challenge_won = False
        while bot.config.fsm_running and time.monotonic() < challenge_deadline:
            if not Agent.IsDead(agent_id) and allegiance_value(agent_id) != 3:
                challenge_won = True
                break
            yield from Routines.Yield.wait(250)

        if challenge_won:
            context = GWContext.AgentArray.GetContext()
            context_agents = context.GetAgentArray() if context is not None else []
            all_agents = list(dict.fromkeys([*AgentArray.GetAgentArray(), *context_agents]))
            reacquired = [
                candidate
                for candidate in all_agents
                if Agent.IsLiving(candidate)
                and (
                    not preferred_model_id
                    or Agent.GetModelID(candidate) == preferred_model_id
                )
                and Utils.Distance(npc_xy, Agent.GetXY(candidate)) <= 350.0
            ]
            if not reacquired:
                SESSION_LOG.write(
                    f"optional_blessing_challenge_reacquire_failed label={label!r}"
                )
                return False
            agent_id = min(
                reacquired,
                key=lambda candidate: Utils.Distance(npc_xy, Agent.GetXY(candidate)),
            )
            yield from bot.Dialogs._coro_pause_hero_ai()
            yield from Routines.Yield.Player.InteractAgent(agent_id)
            final_clicked = yield from click_first_visible_choice(6.0)

            verify_deadline = time.monotonic() + 5.0
            while bot.config.fsm_running and time.monotonic() < verify_deadline:
                if has_eotn_blessing():
                    blessed = True
                    break
                yield from Routines.Yield.wait(100)
            yield from bot.Dialogs._coro_restore_hero_ai()
            SESSION_LOG.write(
                f"optional_blessing_norn_challenge_finished label={label!r} "
                f"agent_id={agent_id} final_clicked={final_clicked} blessed={blessed}"
            )
        else:
            SESSION_LOG.write(
                f"optional_blessing_norn_challenge_timeout label={label!r} "
                f"agent_id={agent_id}"
            )

    SESSION_LOG.write(
        f"optional_blessing_result label={label!r} agent_id={agent_id} "
        f"model_id={Agent.GetModelID(agent_id)} dialog={hex(dialog_id)} "
        f"clicked={clicked} became_hostile={became_hostile} blessed={blessed}"
    )
    if not blessed:
        ConsoleLog(
            MODULE_NAME,
            f"Optional blessing was not confirmed at {label}; continuing the route.",
            Console.MessageType.Warning,
        )
    return blessed


def _take_sepulchre_entrance_blessing() -> Generator[Any, Any, bool]:
    """Take Dwarven Raider from the level-1 Beacon of Droknar."""
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.Py4GWcorelib import Utils
    from Py4GWCoreLib.UIManager import UIManager

    def has_dwarven_raider() -> bool:
        player_id = Player.GetAgentID()
        return any(
            Effects.EffectExists(player_id, effect_id)
            or Effects.BuffExists(player_id, effect_id)
            for effect_id in DWARVEN_RAIDER_EFFECT_IDS
        )

    def active_skill_ids() -> list[int]:
        player_id = Player.GetAgentID()
        values = [
            int(getattr(effect, "skill_id", 0) or 0)
            for effect in Effects.GetEffects(player_id)
        ]
        values.extend(
            int(getattr(buff, "skill_id", 0) or 0)
            for buff in Effects.GetBuffs(player_id)
        )
        return sorted({value for value in values if value > 0})

    context = GWContext.AgentArray.GetContext()
    context_agents = context.GetAgentArray() if context is not None else []
    all_agents = list(dict.fromkeys([*AgentArray.GetAgentArray(), *context_agents]))
    candidates = [
        agent_id
        for agent_id in all_agents
        if Agent.IsLiving(agent_id)
        and Agent.GetModelID(agent_id) == SEPULCHRE_LEVEL1_ENTRANCE_BLESSING_MODEL_ID
        and Utils.Distance(
            SEPULCHRE_LEVEL1_ENTRANCE_BLESSING_XY, Agent.GetXY(agent_id)
        ) <= 400.0
    ]
    if not candidates:
        SESSION_LOG.write(
            "sepulchre_entrance_blessing_lookup_failed "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()} "
            f"target_xy={SEPULCHRE_LEVEL1_ENTRANCE_BLESSING_XY}"
        )
        ConsoleLog(
            MODULE_NAME,
            "Sepulchre entrance Beacon of Droknar was not found.",
            Console.MessageType.Error,
        )
        return False

    agent_id = min(
        candidates,
        key=lambda candidate: Utils.Distance(
            SEPULCHRE_LEVEL1_ENTRANCE_BLESSING_XY, Agent.GetXY(candidate)
        ),
    )
    before_ids = active_skill_ids()
    already_active = has_dwarven_raider()

    yield from bot.Dialogs._coro_pause_hero_ai()
    yield from Routines.Yield.Player.InteractAgent(agent_id)
    fallback_clicked = False
    response_visible = False
    response_deadline = time.monotonic() + 6.0
    while bot.config.fsm_running and time.monotonic() < response_deadline:
        response_visible = UIManager.IsNPCDialogVisible()
        if response_visible:
            button_count = UIManager.GetDialogButtonCount()
            if already_active:
                break
            if button_count > 0:
                fallback_clicked = UIManager.ClickDialogButton(1, debug=False)
                break
        yield from Routines.Yield.wait(100)

    verify_deadline = time.monotonic() + 8.0
    blessed = has_dwarven_raider()
    while bot.config.fsm_running and not blessed and time.monotonic() < verify_deadline:
        yield from Routines.Yield.wait(100)
        blessed = has_dwarven_raider()
    yield from bot.Dialogs._coro_restore_hero_ai()

    after_ids = active_skill_ids()
    SESSION_LOG.write(
        f"sepulchre_entrance_blessing_result agent_id={agent_id} "
        f"model_id={Agent.GetModelID(agent_id)} visible_button_clicked={fallback_clicked} "
        f"already_active={already_active} response_visible={response_visible} blessed={blessed} "
        f"before_skill_ids={before_ids} after_skill_ids={after_ids}"
    )
    if not blessed:
        ConsoleLog(
            MODULE_NAME,
            "The Sepulchre beacon did not grant Dwarven Raider; continuing with the recorded route.",
            Console.MessageType.Warning,
        )
    return blessed


def _follow_sepulchre_fragment_route() -> Generator[Any, Any, bool]:
    SESSION_LOG.write(
        "sepulchre_fragment_route_start "
        f"map={Map.GetMapID()} player_xy={Player.GetXY()} "
        "source_route='ROUTE-20260803-105240-310' "
        f"route_points={len(SEPULCHRE_LEVEL1_FRAGMENT_ROUTE_XY)}"
    )
    success = yield from Routines.Yield.Movement.FollowPath(
        path_points=list(SEPULCHRE_LEVEL1_FRAGMENT_ROUTE_XY),
        tolerance=300.0,
        timeout=-1,
        custom_pause_fn=lambda: Routines.Checks.Agents.InDanger(),
        stop_on_party_wipe=False,
        autopath=False,
    )
    SESSION_LOG.write(
        "sepulchre_fragment_route_finished "
        f"map={Map.GetMapID()} player_xy={Player.GetXY()} success={success} "
        "source_route='ROUTE-20260803-105240-310'"
    )
    return success


def _activate_sepulchre_proof_of_strength() -> Generator[Any, Any, bool]:
    SESSION_LOG.write(
        "sepulchre_proof_strength_start "
        f"map={Map.GetMapID()} player_xy={Player.GetXY()} "
        f"route_points={len(SEPULCHRE_PROOF_OF_STRENGTH_ROUTE_XY)} "
        "activation_xy=(-5366.0,-15794.0)"
    )
    success = yield from Routines.Yield.Movement.FollowPath(
        path_points=list(SEPULCHRE_PROOF_OF_STRENGTH_ROUTE_XY),
        tolerance=50.0,
        timeout=-1,
        custom_pause_fn=lambda: Routines.Checks.Agents.InDanger(),
        stop_on_party_wipe=False,
        autopath=False,
    )
    # Hold briefly on the center while the floor trigger opens the gates.
    yield from Routines.Yield.wait(1500)
    SESSION_LOG.write(
        "sepulchre_proof_strength_finished "
        f"map={Map.GetMapID()} player_xy={Player.GetXY()} success={success}"
    )
    return success


def _interact_artificer_mullenix(
    dialog_id: int,
    *,
    accept_dialog: bool = True,
    click_two_visible_entry_choices: bool = False,
    visible_choice_sequence: tuple[int, ...] = (),
    quest_menu_label: str = "",
    quest_id_to_accept: int = 0,
    quest_menu_choice: int = 0,
    expected_map_id: int = 0,
    reward_quest_id: int = 0,
) -> Generator[Any, Any, bool]:
    """Resolve Mullenix by model, send a dialogue, and optionally accept its window."""
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.FrameTree import Frame, FrameId
    from Py4GWCoreLib.Py4GWcorelib import Utils
    from Py4GWCoreLib.UIManager import UIManager

    def accept_reward_if_visible() -> tuple[bool, str]:
        if UIManager.IsNPCDialogVisible() and UIManager.GetDialogButtonCount() > 0:
            if UIManager.ClickDialogButton(1, debug=False):
                return True, "dialog_button_1"
        accept_button = Frame(FrameId.AcceptButton)
        if not accept_button.exists:
            return False, "none"
        accept_button.click()
        return True, "frame_accept_button"

    if reward_quest_id and int(reward_quest_id) not in {
        int(value) for value in (Quest.GetQuestLogIds() or [])
    }:
        SESSION_LOG.write(
            f"mullenix_reward_skipped quest_id={reward_quest_id} "
            f"dialog={hex(dialog_id)} reason=quest_already_cleared"
        )
        return True

    current_map_id = Map.GetMapID()
    if current_map_id != EOTN_OUTPOST_MAP_ID:
        SESSION_LOG.write(
            "mullenix_wrong_map "
            f"map={current_map_id} required_map={EOTN_OUTPOST_MAP_ID} "
            f"known_quest_instances=({EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID},"
            f"{EOTN_SERVICE_PRACTICE_INSTANCE_MAP_ID})"
        )
        ConsoleLog(
            MODULE_NAME,
            "Artificer Mullenix reward interaction requires the normal Eye of the North outpost (map 642).",
            Console.MessageType.Error,
        )
        bot.config.state_description = "Blocked: Mullenix is in the wrong Eye instance"
        while bot.config.fsm_running:
            yield from Routines.Yield.wait(1000)
        return False

    # A prior attempt may have left the quest/reward window open. Finish that
    # modal before trying to interact with Mullenix through it again.
    if accept_dialog and reward_quest_id:
        accepted, accept_method = accept_reward_if_visible()
        if accepted:
            verify_deadline = time.monotonic() + 6.0
            while bot.config.fsm_running and time.monotonic() < verify_deadline:
                if int(reward_quest_id) not in {
                    int(value) for value in (Quest.GetQuestLogIds() or [])
                }:
                    break
                yield from Routines.Yield.wait(100)
            quest_cleared = int(reward_quest_id) not in {
                int(value) for value in (Quest.GetQuestLogIds() or [])
            }
            SESSION_LOG.write(
                "mullenix_dialog_accepted "
                f"existing_window=True method={accept_method} dialog={hex(dialog_id)} "
                f"quest_id={reward_quest_id} quest_cleared={quest_cleared}"
            )
            if quest_cleared:
                return True

    context = GWContext.AgentArray.GetContext()
    context_agents = context.GetAgentArray() if context is not None else []
    all_agents = list(dict.fromkeys([*AgentArray.GetAgentArray(), *context_agents]))
    candidates = [
        agent_id
        for agent_id in all_agents
        if Agent.IsLiving(agent_id)
        and Agent.GetModelID(agent_id) == ARTIFICER_MULLENIX_MODEL_ID
        and Utils.Distance(ARTIFICER_MULLENIX_XY, Agent.GetXY(agent_id)) <= 500.0
    ]

    resolution = "captured_model"
    if not candidates:
        resolution = "npc_at_captured_position"
        candidates = [
            agent_id
            for agent_id in all_agents
            if Agent.IsLiving(agent_id)
            and Agent.IsNPC(agent_id)
            and Utils.Distance(ARTIFICER_MULLENIX_XY, Agent.GetXY(agent_id)) <= 150.0
        ]

    if not candidates:
        SESSION_LOG.write(
            "mullenix_lookup_failed "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()} "
            f"target_xy={ARTIFICER_MULLENIX_XY} model_id={ARTIFICER_MULLENIX_MODEL_ID} "
            f"shared_count={len(AgentArray.GetAgentArray())} "
            f"context_count={len(context_agents)}"
        )
        ConsoleLog(
            MODULE_NAME,
            "Artificer Mullenix was not found in the live agent array.",
            Console.MessageType.Error,
        )
        bot.config.state_description = "Blocked: Artificer Mullenix not found"
        while bot.config.fsm_running:
            yield from Routines.Yield.wait(1000)
        return False

    agent_id = min(
        candidates,
        key=lambda candidate: Utils.Distance(ARTIFICER_MULLENIX_XY, Agent.GetXY(candidate)),
    )
    start_distance = Utils.Distance(Player.GetXY(), Agent.GetXY(agent_id))
    if start_distance > 150.0:
        movement_success = yield from bot.Move._coro_xy(
            *ARTIFICER_MULLENIX_APPROACH_XY,
            step_name="Approach Artificer Mullenix",
            forced_timeout=15000,
            fail_on_unmanaged=False,
        )
        SESSION_LOG.write(
            f"mullenix_approach start_distance={start_distance:.1f} "
            f"movement_success={movement_success} player_xy={Player.GetXY()}"
        )

    # Runtime IDs can change while moving or after a map load. Rebuild the
    # merged live array and require actual interaction distance before use.
    context = GWContext.AgentArray.GetContext()
    context_agents = context.GetAgentArray() if context is not None else []
    all_agents = list(dict.fromkeys([*AgentArray.GetAgentArray(), *context_agents]))
    candidates = [
        candidate
        for candidate in all_agents
        if Agent.IsLiving(candidate)
        and Agent.GetModelID(candidate) == ARTIFICER_MULLENIX_MODEL_ID
        and Utils.Distance(ARTIFICER_MULLENIX_XY, Agent.GetXY(candidate)) <= 500.0
    ]
    if not candidates:
        SESSION_LOG.write(
            "mullenix_reacquire_failed "
            f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
        )
        return False
    agent_id = min(
        candidates,
        key=lambda candidate: Utils.Distance(
            ARTIFICER_MULLENIX_XY, Agent.GetXY(candidate)
        ),
    )
    player_to_agent = Utils.Distance(Player.GetXY(), Agent.GetXY(agent_id))
    agent_to_capture = Utils.Distance(
        Agent.GetXY(agent_id), ARTIFICER_MULLENIX_XY
    )
    player_to_approach = Utils.Distance(
        Player.GetXY(), ARTIFICER_MULLENIX_APPROACH_XY
    )
    if player_to_agent > 175.0:
        SESSION_LOG.write(
            "mullenix_reacquire_too_far "
            f"agent_id={agent_id} player_to_agent={player_to_agent:.1f} "
            f"player_to_approach={player_to_approach:.1f}"
        )
        return False

    SESSION_LOG.write(
        f"mullenix_lookup_success map={Map.GetMapID()} agent_id={agent_id} "
        f"model_id={Agent.GetModelID(agent_id)} agent_name={Agent.GetNameByID(agent_id)!r} "
        f"agent_xy={Agent.GetXY(agent_id)} player_xy={Player.GetXY()} "
        f"dialog={hex(dialog_id)} resolution={resolution} "
        f"player_to_approach={player_to_approach:.1f} "
        f"player_to_agent={player_to_agent:.1f} "
        f"agent_to_capture={agent_to_capture:.1f}"
    )

    yield from bot.Dialogs._coro_pause_hero_ai()
    yield from Routines.Yield.Player.InteractAgent(agent_id)
    yield from Routines.Yield.wait(500)

    if quest_menu_label and quest_id_to_accept:
        # Generic Frame.click()/button_click reports success but does not
        # activate Mullenix's selectable quest rows. Other working PY4GW
        # selectable dialogs use mouse_click_action(0, 0) on the game thread.
        choice_deadline = time.monotonic() + 12.0
        multi_choice_clicked = False
        single_action_clicks = 0
        total_clicks = 0
        while bot.config.fsm_running and time.monotonic() < choice_deadline:
            quest_log_ids = {
                int(current_id) for current_id in (Quest.GetQuestLogIds() or [])
            }
            if int(quest_id_to_accept) in quest_log_ids:
                yield from bot.Dialogs._coro_restore_hero_ai()
                SESSION_LOG.write(
                    "mullenix_named_quest_accepted "
                    f"quest_id={quest_id_to_accept} label={quest_menu_label!r} "
                    f"clicks={total_clicks}"
                )
                return True

            if not UIManager.IsNPCDialogVisible():
                yield from Routines.Yield.wait(100)
                continue

            buttons = UIManager.GetDialogButtons(debug=False)
            button_count = len(buttons)
            target = None
            action = "none"
            if button_count > 1 and not multi_choice_clicked:
                if 1 <= quest_menu_choice <= button_count:
                    target = buttons[quest_menu_choice - 1]
                    action = f"menu_choice_{quest_menu_choice}"
            elif button_count == 1 and single_action_clicks < 2:
                target = buttons[0]
                action = "single_action"

            if target is not None and target.is_usable:
                if action.startswith("menu_choice_"):
                    multi_choice_clicked = True
                elif action == "single_action":
                    single_action_clicks += 1
                target_frame_id = target.frame_id
                PyGameThread.enqueue(
                    lambda frame=target: frame.mouse_click_action(0, 0)
                )
                total_clicks += 1
                SESSION_LOG.write(
                    "mullenix_quest_mouse_action "
                    f"quest_id={quest_id_to_accept} label={quest_menu_label!r} "
                    f"button_count={button_count} action={action} "
                    f"frame_id={target_frame_id} click_number={total_clicks}"
                )
                yield from Routines.Yield.wait(1000)
                continue

            yield from Routines.Yield.wait(100)

        yield from bot.Dialogs._coro_restore_hero_ai()
        ConsoleLog(
            MODULE_NAME,
            f"Mullenix did not finish accepting {quest_menu_label}.",
            Console.MessageType.Error,
        )
        return False

    choices_to_click = (
        visible_choice_sequence
        if visible_choice_sequence
        else ((1, 1) if click_two_visible_entry_choices else ())
    )
    if choices_to_click:
        for sequence_number, dialog_choice in enumerate(choices_to_click, start=1):
            choice_deadline = time.monotonic() + 5.0
            choice_clicked = False
            while bot.config.fsm_running and time.monotonic() < choice_deadline:
                if (
                    UIManager.IsNPCDialogVisible()
                    and UIManager.GetDialogButtonCount() >= dialog_choice
                ):
                    if UIManager.ClickDialogButton(dialog_choice, debug=False):
                        choice_clicked = True
                        break
                yield from Routines.Yield.wait(100)
            SESSION_LOG.write(
                "mullenix_visible_choice_sequence "
                f"sequence_number={sequence_number} dialog_choice={dialog_choice} "
                f"clicked={choice_clicked} "
                f"expected_dialog={hex(dialog_id)}"
            )
            if not choice_clicked:
                yield from bot.Dialogs._coro_restore_hero_ai()
                ConsoleLog(
                    MODULE_NAME,
                    f"Mullenix dialogue choice {dialog_choice} was not found.",
                    Console.MessageType.Error,
                )
                return False
            yield from Routines.Yield.wait(500)
    else:
        Player.SendDialog(dialog_id)
    if not accept_dialog:
        if expected_map_id:
            map_deadline = time.monotonic() + 12.0
            while bot.config.fsm_running and time.monotonic() < map_deadline:
                if Map.GetMapID() == int(expected_map_id) and Map.IsMapReady():
                    break
                yield from Routines.Yield.wait(100)
            map_verified = (
                Map.GetMapID() == int(expected_map_id) and Map.IsMapReady()
            )
        else:
            yield from Routines.Yield.wait(500)
            map_verified = True
        yield from bot.Dialogs._coro_restore_hero_ai()
        SESSION_LOG.write(
            f"mullenix_dialog_sent agent_id={agent_id} "
            f"model_id={Agent.GetModelID(agent_id)} dialog={hex(dialog_id)} "
            f"accept_dialog=False expected_map_id={expected_map_id} "
            f"map_verified={map_verified} current_map={Map.GetMapID()}"
        )
        return map_verified

    accept_deadline = time.monotonic() + 6.0
    accepted = False
    accept_method = "none"
    while bot.config.fsm_running and time.monotonic() < accept_deadline:
        accepted, accept_method = accept_reward_if_visible()
        if accepted:
            accepted = True
            break
        yield from Routines.Yield.wait(100)
    if accepted and reward_quest_id:
        verify_deadline = time.monotonic() + 6.0
        while bot.config.fsm_running and time.monotonic() < verify_deadline:
            if int(reward_quest_id) not in {
                int(value) for value in (Quest.GetQuestLogIds() or [])
            }:
                break
            yield from Routines.Yield.wait(100)
    elif accepted:
        yield from Routines.Yield.wait(1000)
    quest_cleared = (
        accepted
        and (
            not reward_quest_id
            or int(reward_quest_id) not in {
                int(value) for value in (Quest.GetQuestLogIds() or [])
            }
        )
    )
    yield from bot.Dialogs._coro_restore_hero_ai()
    SESSION_LOG.write(
        f"mullenix_dialog_sent agent_id={agent_id} "
        f"model_id={Agent.GetModelID(agent_id)} dialog={hex(dialog_id)} "
        f"reward_accepted={accepted} accept_method={accept_method} "
        f"reward_quest_id={reward_quest_id} quest_cleared={quest_cleared}"
    )
    if not accepted:
        ConsoleLog(
            MODULE_NAME,
            "Mullenix opened a quest dialogue, but its Accept button was not found.",
            Console.MessageType.Error,
        )
    return quest_cleared


def _accept_mullenix_quest_if_missing(
    quest_id: int,
    dialog_id: int,
    *,
    visible_choice_sequence: tuple[int, ...] = (),
    quest_menu_label: str = "",
    quest_menu_choice: int = 0,
) -> Generator[Any, Any, bool]:
    """Accept a Mullenix quest and hard-stop the route if acceptance fails."""
    quest_log_ids = {int(current_id) for current_id in (Quest.GetQuestLogIds() or [])}
    if int(quest_id) in quest_log_ids:
        SESSION_LOG.write(
            f"mullenix_quest_accept_skipped quest_id={quest_id} "
            f"dialog={hex(dialog_id)} reason=already_in_quest_log"
        )
        return True
    if quest_menu_label:
        accepted = yield from _interact_artificer_mullenix(
                dialog_id,
                accept_dialog=False,
                quest_menu_label=quest_menu_label,
                quest_id_to_accept=quest_id,
                quest_menu_choice=quest_menu_choice,
            )
    elif visible_choice_sequence:
        accepted = yield from _interact_artificer_mullenix(
                dialog_id,
                accept_dialog=False,
                visible_choice_sequence=visible_choice_sequence,
            )
    else:
        accepted = yield from _interact_artificer_mullenix(dialog_id)

    if accepted:
        verify_deadline = time.monotonic() + 6.0
        while bot.config.fsm_running and time.monotonic() < verify_deadline:
            if int(quest_id) in {
                int(value) for value in (Quest.GetQuestLogIds() or [])
            }:
                return True
            yield from Routines.Yield.wait(100)

    SESSION_LOG.write(
        "mullenix_quest_acceptance_hard_stop "
        f"quest_id={quest_id} dialog={hex(dialog_id)} label={quest_menu_label!r}"
    )
    ConsoleLog(
        MODULE_NAME,
        f"Quest {quest_menu_label or quest_id} was not accepted; stopping before travel.",
        Console.MessageType.Error,
    )
    bot.config.state_description = (
        f"Stopped: failed to accept {quest_menu_label or f'quest {quest_id}'}"
    )
    # Do not call Botting.Stop() from inside its own managed coroutine; that
    # removes the active coroutine and can trigger list.remove(x) failures.
    bot.config.FSM.stop()
    bot.config.fsm_running = False
    return False


