def _require_quest_complete_before_travel(
    quest_id: int,
    quest_label: str,
    timeout_seconds: float = 8.0,
) -> Generator[Any, Any, bool]:
    """Never leave an explorable merely because its waypoint route ended."""
    deadline = time.monotonic() + timeout_seconds
    while bot.config.fsm_running and time.monotonic() < deadline:
        if Quest.IsQuestCompleted(quest_id):
            SESSION_LOG.write(
                "quest_completion_gate_passed "
                f"quest_id={quest_id} label={quest_label!r} map={Map.GetMapID()}"
            )
            return True
        yield from Routines.Yield.wait(250)

    SESSION_LOG.write(
        "quest_completion_gate_hard_stop "
        f"quest_id={quest_id} label={quest_label!r} map={Map.GetMapID()} "
        f"player_xy={Player.GetXY()} quest_log={list(Quest.GetQuestLogIds() or [])}"
    )
    ConsoleLog(
        MODULE_NAME,
        f"{quest_label} is not complete; stopping here instead of mapping away.",
        Console.MessageType.Error,
    )
    bot.config.state_description = f"Stopped: {quest_label} is not complete"
    bot.config.FSM.stop()
    bot.config.fsm_running = False
    return False


def _wait_for_normal_eotn_after_dummy_resign() -> Generator[Any, Any, bool]:
    """Wait for the solo quest return without relying on the stale party cache."""
    deadline = time.monotonic() + 30.0
    last_snapshot: tuple[int, bool, int] | None = None
    while bot.config.fsm_running and time.monotonic() < deadline:
        snapshot = (Map.GetMapID(), Map.IsMapReady(), Player.GetAgentID())
        if snapshot != last_snapshot:
            SESSION_LOG.write(
                "dummy_resign_return_wait "
                f"map={snapshot[0]} map_ready={snapshot[1]} player_agent_id={snapshot[2]}"
            )
            last_snapshot = snapshot
        if (
            snapshot[0] == EOTN_OUTPOST_MAP_ID
            and snapshot[1]
            and snapshot[2] != 0
        ):
            yield from Routines.Yield.wait(1000)
            SESSION_LOG.write("dummy_resign_return_ready map=642")
            return True
        yield from Routines.Yield.wait(100)

    ConsoleLog(
        MODULE_NAME,
        "Timed out waiting to return from Service: Practice, Dummy.",
        Console.MessageType.Error,
    )
    SESSION_LOG.write(
        "dummy_resign_return_timeout "
        f"map={Map.GetMapID()} map_ready={Map.IsMapReady()} "
        f"player_agent_id={Player.GetAgentID()}"
    )
    return False


def _defend_eye_and_dodge_snowballs() -> Generator[Any, Any, bool]:
    """Run the timed defense captured in Ebon Escape Snowballs Dodge 2."""
    source_route = "ROUTE-20260803-151839-231"

    def instance_uptime_ms() -> int:
        try:
            return max(0, int(Map.GetInstanceUptime()))
        except Exception:
            return 0

    def wait_until_uptime(target_ms: int) -> Generator[Any, Any, bool]:
        while bot.config.fsm_running and Map.GetMapID() == EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID:
            if instance_uptime_ms() >= target_ms:
                return True
            yield from Routines.Yield.wait(100)
        return Map.GetMapID() != EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID

    SESSION_LOG.write(
        "ebon_escape_defense_started "
        f"source_route={source_route!r} map={Map.GetMapID()} "
        f"instance_uptime_ms={instance_uptime_ms()} player_xy={Player.GetXY()}"
    )

    # The capture's segment clock began after the map became readable. Moving
    # at 69 seconds of native instance uptime gives several seconds of safety
    # before the large recorded dodge began around segment +72 seconds.
    yield from wait_until_uptime(69000)
    if Map.GetMapID() != EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID:
        return True
    dodge_success = yield from bot.Move._coro_xy(
        *EBON_ESCAPE_SNOWBALL_SAFE_XY,
        step_name="Dodge the falling snowballs",
        forced_timeout=12000,
        fail_on_unmanaged=False,
    )
    SESSION_LOG.write(
        "ebon_escape_snowball_dodge "
        f"success={dodge_success} instance_uptime_ms={instance_uptime_ms()} "
        f"player_xy={Player.GetXY()} safe_xy={EBON_ESCAPE_SNOWBALL_SAFE_XY}"
    )

    # Route 2 remained at the safe position until about +101 seconds. Keep a
    # small trailing margin before returning to the defense point.
    yield from wait_until_uptime(105000)
    if Map.GetMapID() != EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID:
        return True
    return_success = yield from bot.Move._coro_xy(
        *EBON_ESCAPE_DEFENSE_XY,
        step_name="Return after the snowballs pass",
        forced_timeout=12000,
        fail_on_unmanaged=False,
    )
    SESSION_LOG.write(
        "ebon_escape_snowball_return "
        f"success={return_success} instance_uptime_ms={instance_uptime_ms()} "
        f"player_xy={Player.GetXY()}"
    )

    # The recorded boss approach began after the later waves and reached its
    # explicit boss marker around segment +162 seconds.
    yield from wait_until_uptime(145000)
    for point in EBON_ESCAPE_BOSS_APPROACH_XY:
        if Map.GetMapID() != EOTN_SERVICE_DEFENSE_INSTANCE_MAP_ID:
            return True
        yield from bot.Move._coro_xy(
            *point,
            step_name="Approach the final Modniir wave",
            forced_timeout=15000,
            fail_on_unmanaged=False,
        )

    SESSION_LOG.write(
        "ebon_escape_boss_approach_finished "
        f"instance_uptime_ms={instance_uptime_ms()} player_xy={Player.GetXY()}"
    )
    return True


