def _hunt_koren_wildrunner() -> Generator[Any, Any, bool]:
    """Find and kill the roaming Koren instead of assuming a fixed position."""
    import time

    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Context import GWContext
    from Py4GWCoreLib.Pathing import AutoPathing
    from Py4GWCoreLib.Py4GWcorelib import Utils

    target_name = "koren wildrunner"

    def full_agent_array() -> list[int]:
        shared_agents = AgentArray.GetAgentArray()
        context = GWContext.AgentArray.GetContext()
        context_agents = context.GetAgentArray() if context is not None else []
        return list(dict.fromkeys([*shared_agents, *context_agents]))

    def named_candidates() -> tuple[list[int], list[int]]:
        living: list[int] = []
        dead: list[int] = []
        for agent_id in full_agent_array():
            try:
                name = (Agent.GetNameByID(agent_id) or "").strip().lower()
                if target_name not in name:
                    continue
                if Agent.IsDead(agent_id):
                    dead.append(agent_id)
                elif Agent.IsLiving(agent_id):
                    living.append(agent_id)
            except Exception:
                continue
        return living, dead

    def hold_failure(message: str) -> Generator[Any, Any, bool]:
        SESSION_LOG.write(f"koren_hunt_failed map={Map.GetMapID()} reason={message}")
        ConsoleLog(MODULE_NAME, message, Console.MessageType.Error)
        bot.config.state_description = f"Blocked: {message}"
        while bot.config.fsm_running:
            yield from Routines.Yield.wait(1000)
        return False

    agent_id = 0
    # Names can take a moment to decode after map load. Search Koren's patrol
    # arc while repeatedly consulting the complete map agent array.
    for search_xy in KOREN_WILDRUNNER_SEARCH_XY:
        for _ in range(10):
            living, dead = named_candidates()
            if living:
                agent_id = min(
                    living,
                    key=lambda candidate: Utils.Distance(Player.GetXY(), Agent.GetXY(candidate)),
                )
                break
            if dead:
                yield from hold_failure(
                    "Koren Wildrunner was already dead; restart the Drakkar Lake instance"
                )
                return False
            yield from Routines.Yield.wait(250)
        if agent_id:
            break

        path = yield from AutoPathing().get_path_to(*search_xy)
        if not path:
            path = [search_xy]
        yield from Routines.Yield.Movement.FollowPath(
            path_points=path,
            tolerance=300.0,
            timeout=45000,
        )

    if not agent_id:
        living, dead = named_candidates()
        if living:
            agent_id = min(
                living,
                key=lambda candidate: Utils.Distance(Player.GetXY(), Agent.GetXY(candidate)),
            )
        elif dead:
            yield from hold_failure(
                "Koren Wildrunner was killed by another group; the quest received no credit"
            )
            return False
        else:
            yield from hold_failure(
                "Koren Wildrunner was not found after sweeping his patrol route"
            )
            return False

    SESSION_LOG.write(
        f"koren_hunt_found map={Map.GetMapID()} agent_id={agent_id} "
        f"model_id={Agent.GetModelID(agent_id)} agent_xy={Agent.GetXY(agent_id)} "
        f"player_xy={Player.GetXY()}"
    )

    deadline = time.monotonic() + 150.0
    while Agent.IsValid(agent_id) and Agent.IsAlive(agent_id):
        if time.monotonic() >= deadline:
            yield from hold_failure("Timed out while chasing Koren Wildrunner")
            return False
        if Routines.Checks.Party.IsPartyWiped() or GLOBAL_CACHE.Party.IsPartyDefeated():
            return False

        yield from Routines.Yield.Player.ChangeTarget(agent_id)
        Player.CallTarget(agent_id)
        target_xy = Agent.GetXY(agent_id)
        distance = Utils.Distance(Player.GetXY(), target_xy)
        if distance > 900.0:
            path = yield from AutoPathing().get_path_to(*target_xy)
            if not path:
                path = [target_xy]
            yield from Routines.Yield.Movement.FollowPath(
                path_points=path,
                custom_exit_condition=lambda target=agent_id: (
                    not Agent.IsValid(target)
                    or Agent.IsDead(target)
                    or Utils.Distance(Player.GetXY(), Agent.GetXY(target)) <= 750.0
                ),
                tolerance=750.0,
                timeout=30000,
            )
        else:
            yield from Routines.Yield.wait(500)

    cleanup_deadline = time.monotonic() + 30.0
    while Routines.Checks.Agents.InDanger() and time.monotonic() < cleanup_deadline:
        yield from Routines.Yield.wait(500)
    SESSION_LOG.write(f"koren_hunt_complete map={Map.GetMapID()} agent_id={agent_id}")
    ConsoleLog(MODULE_NAME, "Koren Wildrunner defeated; continuing Worthy Deeds.", Console.MessageType.Info)
    return True


def draw_window_light(
    self,
    main_child_dimensions: Tuple[int, int] = (520, 360),
    icon_path: str = "",
    iconwidth: int = 96,
    additional_ui: Optional[Callable[[], None]] = None
):


    if not self._config.ini_key_initialized:
        self._config.ini_key = Settings(
            f"BottingClass/bot_{self._config.bot_name}/bot_{self._config.bot_name}.ini",
            "account",
        ).name
        self._config.ini_key_initialized = True

    if not self._config.ini_key:
        return

    if ImGui.Begin(
        ini_key=self._config.ini_key,
        name=self._config.bot_name,
        p_open=True,
        flags=PyImGui.WindowFlags.AlwaysAutoResize,
    ):
        self._draw_main_child(main_child_dimensions, icon_path, iconwidth)
        if additional_ui:
            additional_ui()

    ImGui.End(self._config.ini_key)

    # Draw path like original
    if Routines.Checks.Map.MapValid():
        self.parent.UI.DrawPath(
            self._config.config_properties.follow_path_color.get("value"),
            self._config.config_properties.use_occlusion.is_active(),
            self._config.config_properties.snap_to_ground_segments.get("value"),
            self._config.config_properties.floor_offset.get("value"),
        )

# Monkeypatch UI method
try:
    bot.UI.draw_window = types.MethodType(draw_window_light, bot.UI)
except Exception:
    pass

DEBUG = True
def _log(msg: str, mt=PySystem.Console.MessageType.Warning):
    if not DEBUG:
        return
    try:
        PySystem.Console.Log(MODULE_NAME, msg, mt)
    except Exception:
        pass

def _set_bot_started(value: bool):
    cfg = getattr(bot, "config", None)
    if not cfg:
        return
    for attr in ("bot_started", "bot_running", "started", "is_started"):
        if hasattr(cfg, attr):
            try:
                setattr(cfg, attr, bool(value))
                return
            except Exception:
                pass
    try:
        if hasattr(cfg, "variables") and isinstance(cfg.variables, dict):
            cfg.variables["bot_started"] = bool(value)
    except Exception:
        pass


from Py4GWCoreLib import ConsoleLog, Routines, Player

def UseTome21788AndBuyLichAura(bot, inv_cache) -> "Generator":
    """
    Uses tome item_id=21788, then buys skill 114 (Aura de la Liche).
    inv_cache = ton instance de InventoryCache
    """

    TOME_ITEM_ID = 21788
    SKILL_ID = 114

    # VÃ©rif presence (par item_id exact)
    if inv_cache.GetItemCount(TOME_ITEM_ID) <= 0:
        ConsoleLog("Tome", f"Item ID {TOME_ITEM_ID} not found in inventory.")
        return


    ConsoleLog("Tome", f"Using tome item_id={TOME_ITEM_ID} ...")
