def _ebosc_live_agent_near(
    model_id: int,
    expected_xy: Tuple[float, float],
    radius: float,
) -> int:
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Py4GWcorelib import Utils

    candidates = [
        int(agent_id)
        for agent_id in (AgentArray.GetLivingArray() or [])
        if Agent.IsValid(int(agent_id))
        and Agent.IsLiving(int(agent_id))
        and int(Agent.GetModelID(int(agent_id)) or 0) == int(model_id)
        and Utils.Distance(expected_xy, Agent.GetXY(int(agent_id))) <= float(radius)
    ]
    if not candidates:
        return 0
    return min(
        candidates,
        key=lambda agent_id: Utils.Distance(expected_xy, Agent.GetXY(agent_id)),
    )


def _follow_ebosc_route(
    points: Tuple[Tuple[float, float], ...],
    *,
    pause_on_danger: bool,
) -> Generator[Any, Any, bool]:
    success = yield from Routines.Yield.Movement.FollowPath(
        path_points=list(points),
        tolerance=300.0,
        timeout=-1,
        custom_pause_fn=(
            (lambda: Routines.Checks.Agents.InDanger())
            if pause_on_danger
            else (lambda: False)
        ),
        stop_on_party_wipe=False,
        autopath=False,
    )
    return bool(success)


def _trigger_ebosc_vael_first_appearance() -> Generator[Any, Any, bool]:
    followed = yield from _follow_ebosc_route(
        EBOSC_FIRST_APPEARANCE_ROUTE_XY,
        pause_on_danger=False,
    )
    if not followed:
        return False

    deadline = time.monotonic() + 12.0
    while bot.config.fsm_running and time.monotonic() < deadline:
        if _ebosc_live_agent_near(
            EBOSC_VAEL_MODEL_ID,
            EBOSC_VAEL_FIRST_XY,
            700.0,
        ):
            SESSION_LOG.write(
                "ebosc_first_appearance_confirmed "
                f"map={Map.GetMapID()} player_xy={Player.GetXY()}"
            )
            return True
        yield from Routines.Yield.wait(100)

    # Vael is absent here after this one-time prerequisite has already fired.
    # Re-zoning is the distinguishing action, so do not strand repeat runs.
    SESSION_LOG.write(
        "ebosc_first_appearance_not_observed; continuing with required rezone"
    )
    return True


def _take_ebosc_entry_blessing() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        player_id = Player.GetAgentID()
        return any(
            Effects.EffectExists(player_id, effect_id)
            or Effects.BuffExists(player_id, effect_id)
            for effect_id in EOTN_BLESSING_EFFECT_IDS
        )

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="EBSoC Vanguard blessing outside Longeye",
            profile=InteractionProfile.VISIBLE_CHOICE,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=EBOSC_ENTRY_BLESSING_MODEL_ID,
                expected_xy=EBOSC_ENTRY_BLESSING_XY,
                search_radius=700.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=(-21620.0, 11505.26),
                tolerance=100.0,
                target_tolerance=180.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button=1,
                response_timeout_ms=6_000,
                close_dialog_after_success=False,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.EFFECT_PRESENT,
                value=EOTN_BLESSING_EFFECT_IDS,
                description="Vanguard Patrol is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=6_000,
                retry_delay_ms=500,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260808-223313-910",),
        )
        return InteractionBoundarySpec(
            name="EBSoC route-to-Grothmar entry blessing boundary",
            route_points=EBOSC_ENTRY_BLESSING_STANDOFF_ROUTE_XY,
            route_standoff_xy=EBOSC_ENTRY_BLESSING_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=300.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "EBOSC:ENTRY:BLESSING",
        build_boundary,
        verify,
    )
    if not success:
        ConsoleLog(
            MODULE_NAME,
            "The Grothmar Vanguard blessing was not confirmed; continuing the quest.",
            Console.MessageType.Warning,
        )
    return bool(success)


