def _ebosc_item_name(item_id: int) -> str:
    try:
        GLOBAL_CACHE.Item.RequestName(int(item_id))
        if not GLOBAL_CACHE.Item.IsNameReady(int(item_id)):
            return ""
        return Utils.StripMarkup(
            str(GLOBAL_CACHE.Item.GetName(int(item_id)) or "")
        ).strip()
    except Exception:
        return ""


def _ebosc_inventory_has_intelligence() -> bool:
    inventory_items = ItemArray.GetItemArray(
        [Bag.Backpack, Bag.Belt_Pouch, Bag.Bag_1, Bag.Bag_2]
    )
    return any(
        _ebosc_item_name(int(item_id)).casefold() == "charr intelligence"
        for item_id in (inventory_items or [])
    )


def _collect_ebosc_charr_intelligence() -> Generator[Any, Any, bool]:
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Py4GWcorelib import Utils as CoreUtils

    if _ebosc_inventory_has_intelligence():
        SESSION_LOG.write("ebosc_charr_intelligence already_in_inventory")
        return True

    model_id = 0
    deadline = time.monotonic() + 30.0
    while bot.config.fsm_running and time.monotonic() < deadline:
        for agent_id in AgentArray.GetItemArray() or []:
            item_agent_id = int(agent_id)
            if not Agent.IsValid(item_agent_id) or not Agent.IsItem(item_agent_id):
                continue
            if CoreUtils.Distance(
                EBOSC_CHARR_INTELLIGENCE_XY,
                Agent.GetXY(item_agent_id),
            ) > 1_500.0:
                continue
            item_id = int(Agent.GetItemAgentItemID(item_agent_id) or 0)
            if item_id <= 0:
                continue
            if _ebosc_item_name(item_id).casefold() != "charr intelligence":
                continue
            model_id = int(Item.GetModelID(item_id) or 0)
            if model_id > 0:
                SESSION_LOG.write(
                    "ebosc_charr_intelligence_resolved "
                    f"ground_agent={item_agent_id} item_model={model_id} "
                    f"xy={Agent.GetXY(item_agent_id)}"
                )
                break
        if model_id > 0:
            break
        if _ebosc_inventory_has_intelligence():
            return True
        yield from Routines.Yield.wait(100)

    if model_id <= 0:
        ConsoleLog(
            MODULE_NAME,
            "Charr Intelligence was not found near the captured drop location.",
            Console.MessageType.Error,
        )
        bot.config.state_description = "Blocked: collect Charr Intelligence"
        while bot.config.fsm_running:
            if _ebosc_inventory_has_intelligence():
                return True
            yield from Routines.Yield.wait(250)
        return False

    pickup_tree = Routines.BT.Items.PickupMissionStateGroundItemByModelID(
        model_id=model_id,
        expected_xy=EBOSC_CHARR_INTELLIGENCE_XY,
        search_radius=1_500.0,
        clear_radius=2_000.0,
        clear_settle_ms=1_500,
        timeout_ms=30_000,
        allow_unassigned=True,
        interaction_interval_ms=500,
        aftercast_ms=100,
        log=True,
    )
    try:
        while bot.config.fsm_running:
            status = pickup_tree.tick()
            if status == BehaviorTree.NodeState.SUCCESS:
                state = str(
                    pickup_tree.blackboard.get("mission_state_pickup_state", "")
                )
                success = bool(
                    _ebosc_inventory_has_intelligence()
                    or state == "pickup_verified"
                )
                SESSION_LOG.write(
                    "ebosc_charr_intelligence_pickup "
                    f"state={state!r} success={success}"
                )
                return success
            if status == BehaviorTree.NodeState.FAILURE:
                return False
            yield from Routines.Yield.wait(50)
    finally:
        pickup_tree.reset()
    return False


