def Unlock_ebon_battle_standard_of_courage(bot: Botting) -> None:
    bot.States.AddHeader("[Unlock] Ebon Battle Standard of Courage")
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)

    # First appearance: deliberately do not interact with the entry blessing.
    bot.Map.Travel(target_map_id=650)
    bot.Wait.ForMapLoad(target_map_id=650)
    bot.Properties.ApplyNow("hero_ai", "active", False)
    bot.Properties.ApplyNow("pause_on_danger", "active", False)
    bot.Move.FollowAutoPath(list(EBOSC_LONGEYE_FIRST_EXIT_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(EBOSC_LONGEYE_FIRST_PORTAL_ROUTE_XY), target_map_id=649
    )
    bot.States.AddCustomState(
        _trigger_ebosc_vael_first_appearance,
        "Trigger Vael's first appearance without taking the blessing",
    )

    # Required re-zone, then take the same reliable entry blessing used by
    # Against the Charr before crossing Grothmar to Vael's quest location.
    bot.Map.Travel(target_map_id=650)
    bot.Wait.ForMapLoad(target_map_id=650)
    bot.Move.FollowAutoPath(list(EBOSC_LONGEYE_QUEST_EXIT_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(EBOSC_LONGEYE_QUEST_PORTAL_ROUTE_XY), target_map_id=649
    )
    bot.Properties.ApplyNow("hero_ai", "active", True)
    bot.Properties.ApplyNow("pause_on_danger", "active", True)
    bot.States.AddCustomState(
        _take_ebosc_entry_blessing,
        "Take Vanguard blessing outside Longeye",
    )
    bot.States.AddCustomState(
        _accept_ebosc_from_vael,
        "Reach Vael and accept Be Very Very Quiet",
    )

    # Stealth ownership: do not pause for or engage Torch Harrowkeeper's party.
    bot.Properties.ApplyNow("hero_ai", "active", False)
    bot.Properties.ApplyNow("pause_on_danger", "active", False)
    bot.States.AddCustomState(
        _talk_to_ebosc_vael_midquest,
        "Follow Torch at compass range and talk to Vael",
    )
    bot.States.AddCustomState(
        lambda: _follow_ebosc_route(
            EBOSC_FOLLOW_TORCH_TO_MEETING_WAIT_ROUTE_XY,
            pause_on_danger=False,
        ),
        "Follow Torch to the Charr-Grawl meeting",
    )
    bot.Wait.ForTime(30_000)

    # The named meeting wait has elapsed; combat and pickup may now begin.
    bot.Properties.ApplyNow("hero_ai", "active", True)
    bot.Properties.ApplyNow("pause_on_danger", "active", True)
    bot.States.AddCustomState(
        lambda: _follow_ebosc_route(
            EBOSC_MEETING_ATTACK_ROUTE_XY,
            pause_on_danger=True,
        ),
        "Kill the Charr-Grawl meeting",
    )
    bot.Wait.UntilOutOfCombat()
    bot.States.AddCustomState(
        _collect_ebosc_charr_intelligence,
        "Collect Charr Intelligence",
    )

    bot.Map.Travel(target_map_id=650)
    bot.Wait.ForMapLoad(target_map_id=650)
    bot.Move.FollowAutoPath(list(EBOSC_LONGEYE_REWARD_EXIT_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(EBOSC_LONGEYE_REWARD_PORTAL_ROUTE_XY), target_map_id=649
    )
    bot.States.AddCustomState(
        _claim_ebosc_reward_from_langmar,
        "Claim Ebon Battle Standard of Courage from Captain Langmar",
    )
    bot.UI.CancelSkillRewardWindow()
    bot.States.JumpToStepName("MENU_IDLE")


def _plan_a_has_bundle() -> bool:
    player_id = int(Player.GetAgentID() or 0)
    return bool(player_id and Agent.IsHoldingItem(player_id))


