def _follow_plan_a_while_carrying(
    points: Tuple[Tuple[float, float], ...],
) -> Generator[Any, Any, bool]:
    for point_index, point in enumerate(points):
        if not _plan_a_has_bundle():
            SESSION_LOG.write(
                f"plan_a_bundle_missing before_point={point_index} player_xy={Player.GetXY()}"
            )
            if not (yield from _recover_plan_a_bundle_near_player()):
                bot.config.state_description = "Blocked: recover dropped Plan A Battle Plans"
                while bot.config.fsm_running and not _plan_a_has_bundle():
                    yield from Routines.Yield.wait(250)
                if not bot.config.fsm_running:
                    return False
        followed = yield from _follow_ebosc_route((point,), pause_on_danger=True)
        if not followed:
            return False
        if not _plan_a_has_bundle():
            SESSION_LOG.write(
                f"plan_a_bundle_missing after_point={point_index} player_xy={Player.GetXY()}"
            )
            if not (yield from _recover_plan_a_bundle_near_player()):
                bot.config.state_description = "Blocked: recover dropped Plan A Battle Plans"
                while bot.config.fsm_running and not _plan_a_has_bundle():
                    yield from Routines.Yield.wait(250)
                if not bot.config.fsm_running:
                    return False
    return True


def _take_plan_a_return_blessing() -> Generator[Any, Any, bool]:
    from Py4GWCoreLib.Dialog import get_active_dialog

    def verify(_postcondition: PostconditionSpec) -> bool:
        active = get_active_dialog()
        agent_id = int(getattr(active, "agent_id", 0) or 0)
        return bool(
            agent_id
            and Agent.IsValid(agent_id)
            and int(Agent.GetModelID(agent_id) or 0) == EBOSC_ENTRY_BLESSING_MODEL_ID
        )

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="Plan A return-route Vanguard blessing acknowledgement",
            profile=InteractionProfile.AUTOMATIC_TRIGGER,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=EBOSC_ENTRY_BLESSING_MODEL_ID,
                expected_xy=PLAN_A_RETURN_BLESSING_XY,
                search_radius=1_000.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=PLAN_A_RETURN_BLESSING_APPROACH_XY,
                tolerance=75.0,
                target_tolerance=180.0,
                timeout_ms=15_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.CUSTOM,
                value="plan_a_return_blessing_acknowledged",
                description="Return-route Vanguard NPC acknowledged the player",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=5_000,
                retry_delay_ms=500,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=False,
            source_capture_ids=(
                "NPC-20260914-182425-653",
                "NPC-20260914-182432-334",
            ),
        )
        return InteractionBoundarySpec(
            name="Plan A carry-route-to-return-blessing boundary",
            route_points=(PLAN_A_CARRY_TO_RETURN_BLESSING_STANDOFF_ROUTE_XY[-1],),
            route_standoff_xy=PLAN_A_CARRY_TO_RETURN_BLESSING_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=400.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "PLAN_A:RETURN:BLESSING",
        build_boundary,
        verify,
    )
    return bool(success and _plan_a_has_bundle())


def _claim_plan_a_reward() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return PLAN_A_QUEST_ID not in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    if verify(PostconditionSpec(PostconditionKind.QUEST_CLEARED, PLAN_A_QUEST_ID)):
        return True

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="Plan A reward from Captain Langmar",
            profile=InteractionProfile.REWARD_ACCEPT,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=EBOSC_LANGMAR_MODEL_ID,
                name_contains="Captain Langmar",
                expected_xy=EBOSC_LANGMAR_XY,
                search_radius=700.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=(-21020.90, 12295.30),
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Accept",),
                response_timeout_ms=8_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_CLEARED,
                value=PLAN_A_QUEST_ID,
                description="Plan A left the quest log",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-182606-956",),
        )
        return InteractionBoundarySpec(
            name="Plan A carry-route-to-Langmar reward boundary",
            route_points=(PLAN_A_CARRY_FROM_RETURN_BLESSING_ROUTE_XY[-1],),
            route_standoff_xy=PLAN_A_CARRY_FROM_RETURN_BLESSING_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=300.0,
            interaction=interaction,
        )

    if not _plan_a_has_bundle():
        bot.config.state_description = "Blocked: Battle Plans missing before Captain Langmar"
        while bot.config.fsm_running and not _plan_a_has_bundle():
            yield from Routines.Yield.wait(250)
    success = yield from _run_reliable_interaction_boundary(
        "PLAN_A:LANGMAR:REWARD",
        build_boundary,
        verify,
    )
    if success:
        return True
    bot.config.state_description = "Blocked: claim Sneak Attack from Captain Langmar"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_CLEARED, PLAN_A_QUEST_ID)):
            return True
        yield from Routines.Yield.wait(250)
    return False


def Unlock_sneak_attack(bot: Botting) -> None:
    bot.States.AddHeader("[Unlock] Sneak Attack — Plan A")
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)
    bot.Properties.ApplyNow("hero_ai", "active", True)
    bot.Properties.ApplyNow("pause_on_danger", "active", True)

    # Route source: recovery draft ROUTE-20260914-181305-169 (Plan A).
    # Capture timing is intentionally discarded; only the named 70-second
    # diversion wait at NPC-20260914-181941-139 is replayed.
    bot.Map.Travel(target_map_id=650)
    bot.Wait.ForMapLoad(target_map_id=650)
    bot.Move.FollowAutoPath(list(EBOSC_LONGEYE_QUEST_EXIT_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(EBOSC_LONGEYE_QUEST_PORTAL_ROUTE_XY), target_map_id=649
    )
    bot.States.AddCustomState(
        _accept_plan_a_from_langmar,
        "Talk to Captain Langmar and accept Plan A",
    )
    bot.States.AddCustomState(
        _take_ebosc_entry_blessing,
        "Take Vanguard blessing outside Longeye",
    )
    bot.States.AddCustomState(
        _start_plan_a_with_vael,
        "Cross Grothmar and start Vael's diversion",
    )
    bot.States.AddCustomState(
        lambda: _follow_ebosc_route(
            PLAN_A_VAEL_TO_WAIT_ROUTE_XY,
            pause_on_danger=True,
        ),
        "Reach the Plan A waiting position",
    )
    bot.Wait.ForTime(70_000)
    bot.States.AddCustomState(
        _take_plan_a_battle_plans,
        "Take and carry the Battle Plans",
    )
    bot.States.AddCustomState(
        lambda: _follow_plan_a_while_carrying(
            PLAN_A_CARRY_TO_RETURN_BLESSING_STANDOFF_ROUTE_XY[:-1]
        ),
        "Carry the Battle Plans toward the return blessing",
    )
    bot.States.AddCustomState(
        _take_plan_a_return_blessing,
        "Talk to the Vanguard blessing NPC on the return route",
    )
    bot.States.AddCustomState(
        lambda: _follow_plan_a_while_carrying(
            PLAN_A_CARRY_FROM_RETURN_BLESSING_ROUTE_XY[:-1]
        ),
        "Carry the Battle Plans back to Captain Langmar",
    )
    bot.States.AddCustomState(
        _claim_plan_a_reward,
        "Give Captain Langmar the Battle Plans and claim Sneak Attack",
    )
    bot.UI.CancelSkillRewardWindow()
    bot.States.JumpToStepName("MENU_IDLE")


