def _ff_food_supply_present(target_xy: Tuple[float, float]) -> bool:
    runtime = Py4GWInteractionRuntime(
        pause_automation=lambda: None,
        restore_automation=lambda: None,
        verify=lambda _postcondition: False,
    )
    return runtime.resolve_target(
        TargetSpec(
            kind=TargetKind.LOCATION,
            name_contains="Food Supplies",
            expected_xy=target_xy,
            search_radius=250.0,
        )
    ) is not None


def _poison_ff_food_supply(
    supply_index: int,
    route_points: Tuple[Tuple[float, float], ...],
    approach_xy: Optional[Tuple[float, float]],
) -> Generator[Any, Any, bool]:
    target_xy = FF_FOOD_SUPPLY_XY[supply_index]
    capture_ids = (
        "user-screenshot-codex-clipboard-ca751a02-f94c-46bf-873d-65f76f62c49c",
        "user-screenshot-codex-clipboard-1fe85a75-0a8a-498a-b36f-40f8c7386ce1",
        "user-screenshot-codex-clipboard-77d1bab3-2047-4d1f-851c-df194867888c",
        "user-screenshot-codex-clipboard-fc7c0351-272d-4789-824e-6690f98f987b",
        "user-screenshot-codex-clipboard-25f9fa05-3837-4a96-99d0-46f6aa66134f",
    )

    def verify(_postcondition: PostconditionSpec) -> bool:
        return not _ff_food_supply_present(target_xy)

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name=f"Forbidden Fruit poison Food Supplies {supply_index + 1}",
            profile=InteractionProfile.GADGET,
            target=TargetSpec(
                kind=TargetKind.LOCATION,
                name_contains="Food Supplies",
                expected_xy=target_xy,
                search_radius=900.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=approach_xy,
                tolerance=100.0,
                target_tolerance=350.0,
                timeout_ms=20_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.CUSTOM,
                value=f"forbidden_fruit_supply_{supply_index + 1}_gone",
                description=f"Food Supplies {supply_index + 1} disappeared after poisoning",
            ),
            retry=RetryPolicy(
                max_attempts=4,
                poll_ms=100,
                verify_timeout_ms=5_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=(capture_ids[supply_index],),
        )
        return InteractionBoundarySpec(
            name=f"Forbidden Fruit route-to-Food-Supplies-{supply_index + 1} boundary",
            route_points=route_points,
            route_standoff_xy=route_points[-1],
            route_tolerance=150.0,
            handoff_radius=700.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        f"FORBIDDEN_FRUIT:FOOD_SUPPLY:{supply_index + 1}",
        build_boundary,
        verify,
        pause_on_danger=False,
    )
    if success:
        return True
    bot.config.state_description = f"Blocked: poison Food Supplies {supply_index + 1}"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.CUSTOM, "food_supply_gone")):
            return True
        yield from Routines.Yield.wait(250)
    return False


