def _sugss_vyrrgis_agents() -> List[int]:
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Py4GWcorelib import Utils

    return [
        int(agent_id)
        for agent_id in (AgentArray.GetLivingArray() or [])
        if Agent.IsValid(agent_id)
        and int(Agent.GetModelID(agent_id) or 0) == SUGSS_VYRRGIS_MODEL_ID
        and Utils.Distance(Agent.GetXY(agent_id), SUGSS_VYRRGIS_XY) <= 3_000.0
    ]


def _kill_sugss_vyrrgis_and_confirm() -> Generator[Any, Any, bool]:
    boss_seen = bool(_sugss_vyrrgis_agents())
    for point_index, point in enumerate(SUGSS_WAIT_TO_VYRRGIS_ROUTE_XY):
        if _sugss_vyrrgis_agents():
            boss_seen = True
        if not (yield from _follow_ebosc_route((point,), pause_on_danger=True)):
            return False
        if _sugss_vyrrgis_agents():
            boss_seen = True
        SESSION_LOG.write(
            f"sugss_attack_route_progress point={point_index + 1} "
            f"boss_seen={boss_seen} player_xy={Player.GetXY()}"
        )

    candidates = _sugss_vyrrgis_agents()
    living_candidates = [agent_id for agent_id in candidates if not Agent.IsDead(agent_id)]
    if living_candidates:
        boss_seen = True
        yield from Routines.Yield.Player.ChangeTarget(living_candidates[0])

    deadline = time.monotonic() + 180.0
    settled_since: Optional[float] = None
    while bot.config.fsm_running and time.monotonic() < deadline:
        candidates = _sugss_vyrrgis_agents()
        if candidates:
            boss_seen = True
        living_candidates = [
            agent_id for agent_id in candidates if not Agent.IsDead(agent_id)
        ]
        boss_defeated = boss_seen and not living_candidates
        quest_reports_complete = bool(Quest.IsQuestCompleted(SUGSS_QUEST_ID))
        completion_proven = boss_defeated or (
            quest_reports_complete and not living_candidates
        )
        if completion_proven and not Routines.Checks.Agents.InDanger():
            if settled_since is None:
                settled_since = time.monotonic()
            elif time.monotonic() - settled_since >= 1.0:
                SESSION_LOG.write(
                    "sugss_vyrrgis_defeat_confirmed "
                    f"boss_seen={boss_seen} quest_complete={quest_reports_complete} "
                    f"player_xy={Player.GetXY()}"
                )
                return True
        else:
            settled_since = None
        yield from Routines.Yield.wait(100)

    ConsoleLog(
        MODULE_NAME,
        "Vyrrgis the Pestilent's death was not confirmed; waiting at the stronghold.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: defeat Vyrrgis the Pestilent"
    while bot.config.fsm_running:
        candidates = _sugss_vyrrgis_agents()
        if candidates:
            boss_seen = True
        if (
            (boss_seen and not any(not Agent.IsDead(agent_id) for agent_id in candidates))
            or Quest.IsQuestCompleted(SUGSS_QUEST_ID)
        ) and not Routines.Checks.Agents.InDanger():
            return True
        yield from Routines.Yield.wait(250)
    return False


