def Unlock_weakness_trap(bot: Botting) -> None:
    # This quest is deliberately chained directly after Forbidden Fruit. That
    # leaves the character beside Vael instead of repeating the full Longeye
    # -> Grothmar -> Sacnoth traversal.
    _build_forbidden_fruit_flow(bot, return_to_menu=False)
    bot.States.AddHeader(
        "[Unlock] Weakness Trap — Single Ugly Grawl Seeks Same for Mindless Destruction in Ascalon"
    )
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)
    bot.Properties.ApplyNow("hero_ai", "active", True)
    bot.Properties.ApplyNow("pause_on_danger", "active", True)

    # Route source: completed ROUTE-20260914-195224-221 (SUGSSfMDiA 2).
    # The earlier SUGSSfMDiA capture is intentionally ignored. Capture timing
    # is discarded except for the user's named 40-second diversion wait at
    # NPC-20260914-195328-503.
    bot.States.AddCustomState(
        _accept_sugss_from_vael,
        "Accept Single Ugly Grawl from Vael",
    )
    bot.States.AddCustomState(
        lambda: _follow_ebosc_route(
            SUGSS_VAEL_TO_WAIT_ROUTE_XY,
            pause_on_danger=True,
        ),
        "Reach the hierophant stronghold waiting position",
    )
    bot.Wait.ForTime(40_000)
    bot.States.AddCustomState(
        _kill_sugss_vyrrgis_and_confirm,
        "Kill Vyrrgis the Pestilent and confirm his death",
    )

    bot.Map.Travel(target_map_id=650)
    bot.Wait.ForMapLoad(target_map_id=650)
    bot.Move.FollowAutoPath(list(SUGSS_LONGEYE_EXIT_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(SUGSS_LONGEYE_PORTAL_ROUTE_XY), target_map_id=649
    )
    bot.States.AddCustomState(
        _claim_sugss_reward_from_langmar,
        "Claim Weakness Trap from Captain Langmar",
    )
    bot.UI.CancelSkillRewardWindow()
    bot.States.JumpToStepName("MENU_IDLE")


