def _follow_aojc_leg(
    label: str,
    points: Tuple[Tuple[float, float], ...],
) -> Generator[Any, Any, bool]:
    if int(Map.GetMapID()) == BATTLEDEPTHS_MAP_ID:
        return True
    if int(Map.GetMapID()) != ATTACK_ON_JALIS_INSTANCE_MAP_ID:
        return False
    success = yield from _follow_ebosc_route(points, pause_on_danger=True)
    returned = int(Map.GetMapID()) == BATTLEDEPTHS_MAP_ID
    SESSION_LOG.write(
        f"aojc_patrol_leg label={label!r} success={bool(success)} "
        f"returned={returned} map={Map.GetMapID()} player_xy={Player.GetXY()}"
    )
    return bool(success or returned)


def _run_attack_on_jalis_patrol() -> Generator[Any, Any, bool]:
    legs = (
        ("Point 1", AOJC_OROZAR_TO_POINT_1_ROUTE_XY),
        ("Point 2", AOJC_POINT_1_TO_POINT_2_ROUTE_XY),
        ("Point 1", AOJC_POINT_2_TO_POINT_1_ROUTE_XY),
        ("Point 3", AOJC_POINT_1_TO_POINT_3_ROUTE_XY),
        ("Point 1", AOJC_POINT_3_TO_POINT_1_ROUTE_XY),
        ("Point 4", AOJC_POINT_1_TO_POINT_4_ROUTE_XY),
        ("Point 1", AOJC_POINT_4_TO_POINT_1_ROUTE_XY),
        ("Point 3", AOJC_SECOND_POINT_1_TO_POINT_3_ROUTE_XY),
        ("Point 1", AOJC_SECOND_POINT_3_TO_POINT_1_ROUTE_XY),
        ("Point 4", AOJC_POINT_1_TO_POINT_4_ROUTE_XY),
    )
    for label, points in legs:
        if int(Map.GetMapID()) == BATTLEDEPTHS_MAP_ID:
            return True
        if not (yield from _follow_aojc_leg(label, points)):
            return False

    deadline = time.monotonic() + 600.0
    while bot.config.fsm_running and time.monotonic() < deadline:
        if int(Map.GetMapID()) == BATTLEDEPTHS_MAP_ID:
            SESSION_LOG.write("aojc_automatic_return_confirmed map=625")
            return True
        yield from Routines.Yield.wait(250)

    ConsoleLog(
        MODULE_NAME,
        "Attack on Jalis's Camp did not return to Battledepths; waiting in the instance.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: finish Attack on Jalis's Camp defense"
    while bot.config.fsm_running:
        if int(Map.GetMapID()) == BATTLEDEPTHS_MAP_ID:
            return True
        yield from Routines.Yield.wait(250)
    return False


