def _build_attack_on_jalis_flow(bot: Botting) -> None:
    bot.States.AddHeader("[Unlock] By Ural's Hammer! + Great Dwarf Weapon")
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)
