def _aos_has_blessing() -> bool:
    player_id = Player.GetAgentID()
    return any(
        Effects.EffectExists(player_id, effect_id)
        for effect_id in EOTN_BLESSING_EFFECT_IDS
    )


def _accept_path_to_revelations() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return PATH_TO_REVELATIONS_QUEST_ID in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    def build_spec() -> InteractionSpec:
        return InteractionSpec(
            name="AoS accept The Path to Revelations",
            profile=InteractionProfile.QUEST_CONVERSATION,
            target=TargetSpec(
                kind=TargetKind.NPC,
                name_contains="Kerrsh",
                expected_xy=KERRSH_TARNISHED_HAVEN_XY,
                search_radius=500.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=None,
                tolerance=90.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Accept",),
                scroll_down_before_visible_button_labels=("Accept",),
                response_timeout_ms=12_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_ACTIVE,
                value=PATH_TO_REVELATIONS_QUEST_ID,
                description="The Path to Revelations is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
        )

    success = yield from _run_reliable_interaction(
        "AOS:ACCEPT:QUEST-893",
        build_spec,
        verify,
    )
    if success:
        return True

    ConsoleLog(
        MODULE_NAME,
        "The Path to Revelations was not accepted; stopping before Olafstead.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: accept The Path to Revelations"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_ACTIVE, PATH_TO_REVELATIONS_QUEST_ID)):
            return True
        yield from Routines.Yield.wait(250)
    return False


def _take_olgana_blessing() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return _aos_has_blessing()

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="AoS Olgana Norn blessing",
            profile=InteractionProfile.CHALLENGE_THEN_REINTERACT,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=VARAJAR_OLGANA_MODEL_ID,
                name_contains="Olgana Beartamer",
                expected_xy=VARAJAR_OLGANA_XY,
                search_radius=500.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=VARAJAR_OLGANA_APPROACH_XY,
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Sounds like a plan.",),
                response_timeout_ms=6_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.EFFECT_PRESENT,
                value=EOTN_BLESSING_EFFECT_IDS,
                description="an EOTN title blessing is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
                challenge_timeout_ms=150_000,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-173006-116",),
        )
        return InteractionBoundarySpec(
            name="AoS route-to-Olgana blessing boundary",
            route_points=AIR_OF_SUPERIORITY_TO_BLESSING_ROUTE_XY,
            route_standoff_xy=AIR_OF_SUPERIORITY_TO_BLESSING_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=300.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "AOS:OLGANA:BLESSING",
        build_boundary,
        verify,
    )
    if not success:
        ConsoleLog(
            MODULE_NAME,
            "Olgana's optional Norn blessing was not confirmed; continuing the quest.",
            Console.MessageType.Warning,
        )
    return bool(success)


def _follow_aos_route_to_facets() -> Generator[Any, Any, bool]:
    return bool(
        (
            yield from Routines.Yield.Movement.FollowPath(
                path_points=list(AIR_OF_SUPERIORITY_AFTER_BLESSING_ROUTE_XY),
                tolerance=300.0,
                timeout=-1,
                custom_pause_fn=lambda: Routines.Checks.Agents.InDanger(),
                stop_on_party_wipe=False,
                autopath=False,
            )
        )
    )


def _claim_path_to_revelations_reward() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return PATH_TO_REVELATIONS_QUEST_ID not in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="AoS claim Kerrsh reward",
            profile=InteractionProfile.REWARD_ACCEPT,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=VARAJAR_KERRSH_MODEL_ID,
                name_contains="Kerrsh",
                expected_xy=VARAJAR_KERRSH_XY,
                search_radius=900.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=VARAJAR_KERRSH_APPROACH_XY,
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Accept",),
                scroll_down_before_visible_button_labels=("Accept",),
                response_timeout_ms=12_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_CLEARED,
                value=PATH_TO_REVELATIONS_QUEST_ID,
                description="The Path to Revelations left the quest log",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-173844-279",),
        )
        return InteractionBoundarySpec(
            name="AoS route-to-Kerrsh reward boundary",
            route_points=AIR_OF_SUPERIORITY_REWARD_STANDOFF_ROUTE_XY,
            route_standoff_xy=AIR_OF_SUPERIORITY_REWARD_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=300.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "AOS:KERRSH:REWARD",
        build_boundary,
        verify,
    )
    if success:
        return True

    ConsoleLog(
        MODULE_NAME,
        "Kerrsh's Air of Superiority reward was not confirmed; waiting here.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: claim Air of Superiority reward"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_CLEARED, PATH_TO_REVELATIONS_QUEST_ID)):
            return True
        yield from Routines.Yield.wait(250)
    return False


def Unlock_air_of_superiority(bot: Botting) -> None:
    bot.States.AddHeader("[Unlock] Air of Superiority")
    bot.Map.Travel(target_map_name="Tarnished Haven")
    bot.Wait.ForMapLoad(target_map_name="Tarnished Haven")
    bot.States.AddCustomState(
        _accept_path_to_revelations,
        "Accept The Path to Revelations from Kerrsh",
    )

    bot.Map.Travel(target_map_name="Olafstead")
    bot.Wait.ForMapLoad(target_map_name="Olafstead")
    bot.Move.FollowPathAndExitMap(
        list(AOS_OLAFSTEAD_VARAJAR_PORTAL_ROUTE_XY),
        target_map_name="Varajar Fells",
    )
    bot.Properties.ApplyNow("pause_on_danger", "active", True)
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)
    bot.Properties.ApplyNow("hero_ai", "active", True)

    bot.States.AddCustomState(
        _take_olgana_blessing,
        "Take Olgana's Norn blessing",
    )
    bot.States.AddCustomState(
        _follow_aos_route_to_facets,
        "Follow captured Olafstead route to the Facets",
    )
    bot.States.AddCustomState(
        lambda: _require_quest_complete_before_travel(
            PATH_TO_REVELATIONS_QUEST_ID,
            "The Path to Revelations",
            timeout_seconds=180.0,
        ),
        "Wait for The Path to Revelations completion",
    )
    bot.States.AddCustomState(
        _claim_path_to_revelations_reward,
        "Claim Air of Superiority from Kerrsh",
    )
    bot.UI.CancelSkillRewardWindow()
    bot.States.JumpToStepName("MENU_IDLE")




