def _obnw_quest_active() -> bool:
    return OBNW_QUEST_ID in {
        int(value) for value in (Quest.GetQuestLogIds() or [])
    }


def _follow_obnw_route(
    points: Tuple[Tuple[float, float], ...],
    *,
    pause_on_danger: bool = True,
) -> Generator[Any, Any, bool]:
    """Replay quest-trigger geometry without cutting the named waypoints."""
    success = yield from Routines.Yield.Movement.FollowPath(
        path_points=list(points),
        tolerance=100.0,
        timeout=-1,
        custom_pause_fn=(
            (lambda: Routines.Checks.Agents.InDanger())
            if pause_on_danger
            else (lambda: False)
        ),
        stop_on_party_wipe=False,
        autopath=False,
    )
    return bool(success)


def _accept_obnw_from_blorf() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return _obnw_quest_active()

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="Accept O Brave New World from Blorf",
            profile=InteractionProfile.QUEST_CONVERSATION,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=OBNW_BLORF_MODEL_ID,
                name_contains="Blorf",
                expected_xy=OBNW_BLORF_XY,
                search_radius=1_400.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=(14066.16, 16085.66),
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=(
                    'All right, if you promise to never call me "beefy" again.',
                ),
                response_timeout_ms=10_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_ACTIVE,
                value=OBNW_QUEST_ID,
                description="O Brave New World is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-205708-205",),
        )
        return InteractionBoundarySpec(
            name="O Brave New World route-to-Blorf acceptance boundary",
            route_points=OBNW_VLOX_TO_BLORF_STANDOFF_ROUTE_XY,
            route_standoff_xy=OBNW_VLOX_TO_BLORF_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=1_300.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "OBNW:BLORF:ACCEPT", build_boundary, verify
    )
    if success:
        return True
    bot.config.state_description = "Blocked: accept O Brave New World"
    while bot.config.fsm_running:
        if _obnw_quest_active():
            return True
        yield from Routines.Yield.wait(250)
    return False


def _take_obnw_first_blessing() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        player_id = Player.GetAgentID()
        return any(
            Effects.EffectExists(player_id, effect_id)
            for effect_id in EOTN_BLESSING_EFFECT_IDS
        )

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="O Brave New World entrance Asuran blessing",
            profile=InteractionProfile.VISIBLE_CHOICE,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=OBNW_FIRST_BLESSING_MODEL_ID,
                name_contains="Big Machine Krewe Member",
                expected_xy=OBNW_FIRST_BLESSING_XY,
                search_radius=700.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=(16314.79, 11640.41),
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=(
                    "I'll get right on that whole clearing the area thing.",
                ),
                response_timeout_ms=8_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.EFFECT_PRESENT,
                value=EOTN_BLESSING_EFFECT_IDS,
                description="an EOTN title blessing is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-205818-818",),
        )
        return InteractionBoundarySpec(
            name="O Brave New World route-to-first-blessing boundary",
            route_points=OBNW_ARBOR_ENTRY_TO_BLESSING_STANDOFF_ROUTE_XY,
            route_standoff_xy=OBNW_ARBOR_ENTRY_TO_BLESSING_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=700.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "OBNW:BLESSING:FIRST", build_boundary, verify
    )
    if success:
        return True
    bot.config.state_description = "Blocked: take O Brave New World blessing"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.EFFECT_PRESENT, EOTN_BLESSING_EFFECT_IDS)):
            return True
        yield from Routines.Yield.wait(250)
    return False


