def _obnw_shock_agents() -> List[int]:
    from Py4GWCoreLib.AgentArray import AgentArray
    from Py4GWCoreLib.Py4GWcorelib import Utils

    return [
        int(agent_id)
        for agent_id in (AgentArray.GetLivingArray() or [])
        if Agent.IsValid(int(agent_id))
        and Agent.IsLiving(int(agent_id))
        and int(Agent.GetModelID(int(agent_id)) or 0)
        == OBNW_SHOCK_OF_DESTRUCTION_MODEL_ID
        and Utils.Distance(
            Agent.GetXY(int(agent_id)), OBNW_SHOCK_OF_DESTRUCTION_XY
        ) <= 3_000.0
    ]


def _defend_obnw_work_krewe() -> Generator[Any, Any, bool]:
    from Py4GWCoreLib.Py4GWcorelib import Utils

    if not (yield from _follow_obnw_route(OBNW_TO_DEFEND_ROUTE_XY)):
        return False
    GLOBAL_CACHE.Party.Heroes.FlagAllHeroes(*OBNW_DEFEND_XY)
    SESSION_LOG.write(
        f"obnw_defense_flagged defend_xy={OBNW_DEFEND_XY} "
        f"capture=NPC-20260914-210350-339"
    )

    boss_engaged = False
    completed_since: Optional[float] = None
    deadline = time.monotonic() + 900.0
    while bot.config.fsm_running and time.monotonic() < deadline:
        quest_complete = bool(Quest.IsQuestCompleted(OBNW_QUEST_ID))
        in_danger = bool(Routines.Checks.Agents.InDanger())
        if quest_complete and not in_danger:
            if completed_since is None:
                completed_since = time.monotonic()
            elif time.monotonic() - completed_since >= 1.0:
                GLOBAL_CACHE.Party.Heroes.UnflagAllHeroes()
                SESSION_LOG.write(
                    "obnw_defense_complete quest_id=897 boss_model=6141"
                )
                return True
        else:
            completed_since = None

        living_bosses = [
            agent_id for agent_id in _obnw_shock_agents()
            if not Agent.IsDead(agent_id)
        ]
        if living_bosses and not boss_engaged:
            boss_engaged = True
            GLOBAL_CACHE.Party.Heroes.UnflagAllHeroes()
            SESSION_LOG.write(
                "obnw_shock_seen unflagging_heroes_and_advancing "
                f"agent_id={living_bosses[0]}"
            )
            if not (
                yield from _follow_obnw_route(
                    OBNW_BOSS_TRIGGER_ROUTE_XY,
                    pause_on_danger=False,
                )
            ):
                return False
            living_bosses = [
                agent_id for agent_id in _obnw_shock_agents()
                if not Agent.IsDead(agent_id)
            ]
            if living_bosses:
                yield from Routines.Yield.Player.ChangeTarget(living_bosses[0])
        elif (
            not boss_engaged
            and not in_danger
            and Utils.Distance(Player.GetXY(), OBNW_DEFEND_XY) > 250.0
        ):
            if not (yield from _follow_obnw_route((OBNW_DEFEND_XY,))):
                return False

        yield from Routines.Yield.wait(100)

    GLOBAL_CACHE.Party.Heroes.UnflagAllHeroes()
    ConsoleLog(
        MODULE_NAME,
        "O Brave New World completion was not confirmed; waiting in Arbor Bay.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: defend the O Brave New World work krewe"
    while bot.config.fsm_running:
        if Quest.IsQuestCompleted(OBNW_QUEST_ID):
            GLOBAL_CACHE.Party.Heroes.UnflagAllHeroes()
            return True
        yield from Routines.Yield.wait(250)
    return False


def _claim_obnw_reward_from_blorf() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return OBNW_QUEST_ID not in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="Claim Mindbender from Blorf",
            profile=InteractionProfile.REWARD_ACCEPT,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=OBNW_BLORF_MODEL_ID,
                name_contains="Blorf",
                expected_xy=OBNW_BLORF_XY,
                search_radius=700.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=(14075.68, 16098.16),
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Accept",),
                response_timeout_ms=10_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_CLEARED,
                value=OBNW_QUEST_ID,
                description="O Brave New World left the quest log",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=False,
            source_capture_ids=("NPC-20260914-211252-051",),
        )
        return InteractionBoundarySpec(
            name="O Brave New World route-to-Blorf reward boundary",
            route_points=OBNW_REWARD_STANDOFF_ROUTE_XY,
            route_standoff_xy=OBNW_REWARD_STANDOFF_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=500.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "OBNW:BLORF:REWARD", build_boundary, verify
    )
    if success:
        return True
    bot.config.state_description = "Blocked: claim Mindbender from Blorf"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_CLEARED, OBNW_QUEST_ID)):
            return True
        yield from Routines.Yield.wait(250)
    return False


def Unlock_mindbender(bot: Botting) -> None:
    bot.States.AddHeader("[Unlock] Mindbender — O Brave New World")
    bot.Properties.ApplyNow("halt_on_death", "active", True)
    bot.Properties.ApplyNow("movement_timeout", "value", 15000)
    bot.Properties.ApplyNow("hero_ai", "active", True)
    bot.Properties.ApplyNow("pause_on_danger", "active", True)

    # Route source: completed ROUTE-20260914-205651-255
    # (O Brave New World). The capture's live chronology places the second
    # blessing between Waypoints 1 and 2. The three quest waypoints use a
    # tighter route tolerance so they are walked over instead of corner-cut.
    bot.Map.Travel(target_map_id=OBNW_VLOXS_FALLS_MAP_ID)
    bot.Wait.ForMapLoad(target_map_id=OBNW_VLOXS_FALLS_MAP_ID)
    bot.States.AddCustomState(
        _accept_obnw_from_blorf,
        "Accept O Brave New World from Blorf",
    )
    bot.Move.FollowAutoPath(list(OBNW_VLOX_TO_ARBOR_PORTAL_APPROACH_ROUTE_XY))
    bot.Move.FollowPathAndExitMap(
        list(OBNW_VLOX_ARBOR_PORTAL_ROUTE_XY),
        target_map_id=OBNW_ARBOR_BAY_MAP_ID,
    )
    bot.Wait.ForMapLoad(target_map_id=OBNW_ARBOR_BAY_MAP_ID)
    bot.States.AddCustomState(
        _take_obnw_first_blessing,
        "Take the Asuran blessing outside Vlox's Falls",
    )
    bot.States.AddCustomState(
        _continue_obnw_with_erff_first,
        "Tell Erff to begin scouting Arbor Bay",
    )
    bot.States.AddCustomState(
        lambda: _follow_obnw_route(OBNW_ERFF_TO_WAYPOINT_1_ROUTE_XY),
        "Walk over O Brave New World Waypoint 1",
    )
    bot.States.AddCustomState(
        _take_obnw_second_blessing,
        "Take the second Asuran helper blessing",
    )
    bot.States.AddCustomState(
        lambda: _follow_obnw_route(OBNW_SECOND_BLESSING_TO_WAYPOINT_2_ROUTE_XY),
        "Walk over O Brave New World Waypoint 2",
    )
    bot.States.AddCustomState(
        _continue_obnw_with_erff_final,
        "Walk over Waypoint 3 and tell Erff to defend the settlement",
    )
    bot.States.AddCustomState(
        _defend_obnw_work_krewe,
        "Defend the work krewe and kill Shock of Destruction",
    )
    bot.Map.Travel(target_map_id=OBNW_VLOXS_FALLS_MAP_ID)
    bot.Wait.ForMapLoad(target_map_id=OBNW_VLOXS_FALLS_MAP_ID)
    bot.States.AddCustomState(
        _claim_obnw_reward_from_blorf,
        "Claim Mindbender from Blorf",
    )
    bot.UI.CancelSkillRewardWindow()
    bot.States.JumpToStepName("MENU_IDLE")


