def _accept_truthseeker_from_gunnar() -> Generator[Any, Any, bool]:
    def verify(_postcondition: PostconditionSpec) -> bool:
        return TRUTHSEEKER_QUEST_ID in {
            int(value) for value in (Quest.GetQuestLogIds() or [])
        }

    def build_boundary() -> InteractionBoundarySpec:
        interaction = InteractionSpec(
            name="IATS accept Truthseeker from Gunnar",
            profile=InteractionProfile.QUEST_CONVERSATION,
            target=TargetSpec(
                kind=TargetKind.NPC,
                model_id=GUNNAR_POUNDFIST_MODEL_ID,
                name_contains="Gunnar Poundfist",
                expected_xy=GUNNAR_POUNDFIST_XY,
                search_radius=700.0,
            ),
            approach=ApproachSpec(
                player_approach_xy=GUNNAR_POUNDFIST_APPROACH_XY,
                tolerance=75.0,
                target_tolerance=150.0,
                timeout_ms=15_000,
            ),
            dialog=DialogSpec(
                visible_button_labels=("Power, hmmm? I like the sound of that.",),
                scroll_down_before_visible_button_labels=(
                    "Power, hmmm? I like the sound of that.",
                ),
                response_timeout_ms=12_000,
            ),
            postcondition=PostconditionSpec(
                kind=PostconditionKind.QUEST_ACTIVE,
                value=TRUTHSEEKER_QUEST_ID,
                description="Truthseeker is active",
            ),
            retry=RetryPolicy(
                max_attempts=3,
                poll_ms=100,
                verify_timeout_ms=8_000,
                retry_delay_ms=750,
                pause_settle_ms=350,
            ),
            allow_preexisting_postcondition=True,
            source_capture_ids=("NPC-20260914-175251-597",),
        )
        return InteractionBoundarySpec(
            name="IATS route-to-Gunnar quest boundary",
            route_points=IATS_GUNNAR_ROUTE_XY,
            route_standoff_xy=IATS_GUNNAR_ROUTE_XY[-1],
            route_tolerance=150.0,
            handoff_radius=300.0,
            interaction=interaction,
        )

    success = yield from _run_reliable_interaction_boundary(
        "IATS:GUNNAR:QUEST-838",
        build_boundary,
        verify,
    )
    if success:
        return True

    ConsoleLog(
        MODULE_NAME,
        "Truthseeker was not accepted; waiting in Gunnar's Hold.",
        Console.MessageType.Error,
    )
    bot.config.state_description = "Blocked: accept Truthseeker from Gunnar"
    while bot.config.fsm_running:
        if verify(PostconditionSpec(PostconditionKind.QUEST_ACTIVE, TRUTHSEEKER_QUEST_ID)):
            return True
        yield from Routines.Yield.wait(250)
    return False


